insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('schdrofgesetz', 'Schdrofgesetz', '', '', '', '', 'Strafgesetz', '[{"kategorie": "jur.", "text": "\"gesetzliche Vorschrift, die bestimmte Verhaltensweisen als strafbar erklärt und festlegt, welche Strafen oder Maßnahmen für deren Begehung vorgesehen sind\""}, {"kategorie": "", "text": "Strafgesetze dienen dem Schutz wichtiger [[Rechtsgüter]] wie Leben, Gesundheit, Eigentum und öffentliche Sicherheit. Sie bilden die Grundlage des [[Strafrechts]] und sind zentral für die Wahrung der [[Rechtsordnung]]"}, {"kategorie": "", "text": "Wesentliche Merkmale eines Strafgesetzes:  (i) Tatbestandsbeschreibung: Ein Strafgesetz definiert genau, welches Verhalten unter Strafe gestellt ist. Dazu gehören sowohl vorsätzliche als auch fahrlässige Handlungen oder Unterlassungen;  (ii) Rechtsfolgen: Es legt fest, welche Sanktionen – wie Geldstrafen, Freiheitsstrafen oder andere Maßnahmen – bei einem Verstoß verhängt werden können;  (iii) Nach dem Grundsatz à„nulla poena sine lege“ (keine Strafe ohne Gesetz) dürfen nur solche Handlungen bestraft werden, die zuvor im Gesetz als strafbar festgelegt wurden"}, {"kategorie": "", "text": "Strafgesetze finden sich vor allem im [[Strafgesetzbuch]] (StGB), das grundlegende [[Straftatbestände]] wie Diebstahl, Körperverletzung oder Betrug definiert. Daneben existieren auch strafrechtliche Vorschriften in Spezialgesetzen, etwa im Suchtmittelgesetz oder Umweltrecht"}, {"kategorie": "", "text": "Strafgesetze dienen der Abschreckung und Bestrafung von [[Straftaten]] und schützen die [[Gesellschaft]], indem sie klare Regeln für zulässiges und unzulässiges Verhalten festlegen."}]'::jsonb, ''),
  ('schdrofsochn', 'Schdrofsochn', '', '', '', '', 'Strafsachen', '[{"kategorie": "jur.", "text": "\"gerichtliche Verfahren, die sich mit der Untersuchung und Ahndung von [[Straftaten]] befassen\""}, {"kategorie": "", "text": "Strafsachen betreffen Fälle, in denen der Verdacht besteht, dass eine Person gegen das [[Strafrecht]] verstoßen hat, und umfassen die Ermittlung, Anklage, Verhandlung und Verurteilung von [[Straftätern]]"}, {"kategorie": "", "text": "Strafsachen werden in [[Strafgerichten]] verhandelt und von der [[Staatsanwaltschaft]] verfolgt, die das öffentliche Interesse vertritt"}, {"kategorie": "", "text": "Merkmale von Strafsachen:  (i) [[Straftatbestände]]: Strafsachen befassen sich mit Verstößen gegen das [[Strafgesetz]], wie Diebstahl, Körperverletzung, Betrug oder schwerwiegendere Delikte wie Raub oder Mord;  (ii) Staatliche Verfolgung: Strafsachen werden im Namen des [[Staates]] verfolgt, meist durch die [[Staatsanwaltschaft]], die eine [[Anklage]] erhebt, wenn hinreichender Tatverdacht besteht;  (iii) Ziele und Sanktionen: In Strafsachen geht es um die Feststellung von Schuld und Unschuld sowie um die Verhängung von Strafen wie Geldstrafen, Freiheitsstrafen oder gemeinnützige Arbeit"}, {"kategorie": "", "text": "Ermittlungsverfahren: Die [[Polizei]] und [[Staatsanwaltschaft]] untersuchen den Tatverdacht, sammeln Beweise und führen Vernehmungen durch"}, {"kategorie": "", "text": "Hauptverhandlung: Falls Anklage erhoben wird, kommt es zur Hauptverhandlung vor dem [[Strafgericht]], wo Beweise präsentiert und Zeugen gehört werden"}, {"kategorie": "", "text": "Urteilsfindung: Das Gericht entscheidet über Schuld und Strafe oder spricht einen Freispruch aus, wenn die Beweise nicht ausreichen"}, {"kategorie": "", "text": "Strafsachen dienen der Aufrechterhaltung der [[öffentlichen]] Ordnung und Sicherheit und sollen durch die Ahndung von Straftaten potenzielle Täter abschrecken und das Vertrauen in das Rechtssystem stärken."}]'::jsonb, ''),
  ('zivueuesochn', 'Zivüüsochn', '', '', '', '', 'Zivilsachen', '[{"kategorie": "jur.", "text": "\"gerichtliche Verfahren, die sich mit Streitigkeiten im Bereich des [[Zivilrechts]] zwischen Privatpersonen, Unternehmen oder anderen juristischen Personen befassen\""}, {"kategorie": "", "text": "Sie umfassen alle Fälle, in denen keine [[Straftat]] verfolgt wird, sondern private Rechte und Pflichten geklärt werden müssen"}, {"kategorie": "", "text": "In Zivilsachen geht es oft um die Durchsetzung von Ansprüchen und den Schutz privater Interessen"}, {"kategorie": "", "text": "Merkmale von Zivilsachen:  (i)Streitgegenstände: Zivilsachen betreffen oft Vertragsstreitigkeiten (z. B. Kauf-, Miet-, oder Arbeitsverträge), Schadensersatzforderungen, [[Familienrecht]] (z.B. [[Scheidung]], [[Unterhalt]]) und [[Erbschaftsangelegenheiten]];  (ii) [[Privatautonomie]]: Im Gegensatz zum [[Strafrecht]] agieren die [[Parteien]] in Zivilsachen gleichberechtigt; der [[Staat]] greift nur durch das [[Gericht]] als neutralen Schiedsrichter ein;  (iii) Rechtsfolgen: Zivilsachen führen zu gerichtlichen Entscheidungen über Ansprüche, wie Zahlung von Geldbeträgen, Herausgabe von Eigentum oder Festlegung von Pflichten und Rechten der Parteien"}, {"kategorie": "", "text": "Ablauf des Zivilverfahrens:  (i) Klageerhebung: Die klagende Partei bringt ihren Anspruch durch eine [[Klage]] vor Gericht, die beklagte Partei kann sich verteidigen;  (ii) Gerichtsverhandlung: Beweise werden vorgelegt, und die Parteien tragen ihre Argumente vor. Das Gericht prüft die Ansprüche und wägt die [[Beweise]] ab;  (iii) Urteilsfindung: Das Gericht fällt ein Urteil, das den Streit klärt und die Rechte und Pflichten der Parteien festlegt"}, {"kategorie": "", "text": "Zweck von Zivilsachen: Zivilsachen dienen dazu, private Ansprüche und Rechte verbindlich zu klären und damit das friedliche Zusammenleben und wirtschaftliche Handeln zu sichern. Sie fördern die [[Rechtssicherheit]], indem sie verbindliche Entscheidungen bei rechtlichen Konflikten schaffen."}]'::jsonb, ''),
  ('rechtsoadnung', 'Rechtsoadnung', '', '', '', '', 'Rechtsordnung', '[{"kategorie": "jur.", "text": "\"das System aller verbindlichen [[Rechtsnormen]] eines [[Staates]], das die Beziehungen zwischen [[Bürgern]] sowie zwischen Staat und Bürgern regelt\""}, {"kategorie": "", "text": "Sie umfasst [[Gesetze]], [[Verordnungen]] und [[Gewohnheitsrecht]] und legt fest, welches Verhalten erlaubt oder verboten ist"}, {"kategorie": "", "text": "Wesentliche Merkmale:  (i) Verbindlichkeit: Die Rechtsordnung ist für alle Mitglieder der [[Gesellschaft]] bindend und wird durch staatliche Institutionen durchgesetzt;  (ii) Rechtsbereiche: Die Rechtsordnung gliedert sich in [[Zivilrecht]], [[Strafrecht]] und [[Öffentliches]] Recht, um verschiedene Lebensbereiche zu regeln;  (iii) Normenhierarchie: Die Rechtsordnung folgt einer Rangordnung der Normen, in der das [[Verfassungsrecht]] an höchster Stelle steht, gefolgt von einfachen Gesetzen, Verordnungen und untergeordneten Regeln. Diese Hierarchie stellt sicher, dass alle [[Rechtsnormen]] im Einklang mit der Verfassung stehen"}, {"kategorie": "", "text": "Die Rechtsordnung sorgt für Ordnung, Gerechtigkeit und Konfliktlösung und bildet das Fundament für ein friedliches und gerechtes Zusammenleben in der [[Gesellschaft]]."}]'::jsonb, ''),
  ('rechtssichaheit', 'Rechtssichaheit', '', '', '', '', 'Rechtssicherheit', '[{"kategorie": "jur.", "text": "\"Grundprinzip des [[Rechtsstaats]], das sicherstellt, dass [[Rechtsnormen]] klar, vorhersehbar und verlässlich sind\""}, {"kategorie": "", "text": "\"Rechtssicherheit\" bedeutet, dass [[Bürger]] und Unternehmen darauf vertrauen können, dass geltende [[Gesetze]] und Regeln beständig und durchschaubar sind, und dass ihre Rechte und Pflichten eindeutig definiert sind"}, {"kategorie": "", "text": "Wesentliche Merkmale der Rechtssicherheit:  (i) Verlässlichkeit und Stabilität: Gesetze sollen über längere Zeiträume beständig sein, damit Bürger und Unternehmen planen und handeln können;  (ii) Vorhersehbarkeit: Regeln müssen so formuliert sein, dass die Rechtsfolgen eines Verhaltens im Voraus erkennbar sind;  (iii) Rechtsschutz: Bürger haben Anspruch auf unabhängige Gerichte, die ihre Rechte verteidigen und Willkür verhindern"}, {"kategorie": "", "text": "Rechtssicherheit schützt vor willkürlichem staatlichen Handeln und fördert das Vertrauen in das [[Rechtssystem]], da sie gewährleistet, dass [[Rechtsnormen]] verlässlich und gerecht angewendet werden."}]'::jsonb, ''),
  ('gewohnheitsrecht', 'Gewohnheitsrecht', '', '', '', '', 'Gewohnheitsrecht', '[{"kategorie": "jur.", "text": "\"ungeschriebenes Recht, das sich aus langjähriger, beständiger Praxis und allgemeiner Anerkennung innerhalb einer Gemeinschaft entwickelt hat\""}, {"kategorie": "", "text": "Es entsteht, wenn bestimmte Verhaltensweisen über einen langen Zeitraum hinweg regelmäßig praktiziert und als verbindlich angesehen werden, obwohl sie nicht in Gesetzen festgelegt sind"}, {"kategorie": "", "text": "Merkmale des Gewohnheitsrechts:  (i) Allgemeine Anerkennung: Die Regel muss von der Mehrheit der betroffenen Personen als rechtlich verbindlich angesehen werden;  (ii) Langjährige Übung: Die Praxis muss über längere Zeit hinweg konstant und einheitlich ausgeübt worden sein;  (iii) Fehlende schriftliche Norm: Im Gegensatz zu gesetztem Recht ist Gewohnheitsrecht nicht in schriftlichen Gesetzen oder Verordnungen festgelegt"}, {"kategorie": "", "text": "Gewohnheitsrecht ergänzt das geschriebene Recht und kann bei fehlenden gesetzlichen Regelungen als Grundlage für gerichtliche Entscheidungen herangezogen werden. Es spielt insbesondere im Völkerrecht eine zentrale Rolle, wo es als Grundlage für Normen und Verhaltensregeln zwischen Staaten dient. Beispiele sind die Regelungen zur Staatensouveränität oder das Verbot der Angriffskriege."}]'::jsonb, ''),
  ('vawoitungsgericht', 'Vawoitungsgericht', '', '', '', '', 'Verwaltungsgericht', '[{"kategorie": "allg.", "text": "\"Gericht der Verwaltungsgerichtsbarkeit, das für die Überprüfung von Entscheidungen und Handlungen der öffentlichen Verwaltung zuständig ist\""}, {"kategorie": "", "text": "Verwaltungsgerichte sind eigenständige Gerichte und unabhängig von der ordentlichen Gerichtsbarkeit (Zivil- und Strafgerichte)"}, {"kategorie": "", "text": "Sie sind speziell dafür eingerichtet, [[Bürgern]] die Möglichkeit zu geben, gegen behördliche Bescheide und Maßnahmen des Staates oder der Länder Rechtsmittel einzulegen"}, {"kategorie": "", "text": "Seit der Verwaltungsgerichtsbarkeits-Novelle 2012, die im Jahr 2014 in Kraft trat, ist die Verwaltungsgerichtsbarkeit in Österreich zweistufig organisiert:  (i) Verwaltungsgerichte erster Instanz (Landes- und Bundesebene): [[Landesverwaltungsgericht]]: Jedes Bundesland hat sein eigenes Verwaltungsgericht, das für die Überprüfung von Bescheiden der Landes- und Gemeindebehörden zuständig ist;  (ii) [[Bundesverwaltungsgericht]] (BVwG): Dieses Gericht ist für die Überprüfung von Bescheiden der Bundesbehörden (z.B. im Asyl- oder Sozialversicherungsrecht) zuständig;  (iii) [[Bundesfinanzgericht]] (BFG): Das Bundesfinanzgericht behandelt Beschwerden im Bereich des Finanz- und Abgabenrechts;  (iv) [[Verwaltungsgerichtshof]] (VwGH): Der Verwaltungsgerichtshof ist das oberste Verwaltungsgericht in Österreich und prüft Entscheidungen der erstinstanzlichen Verwaltungsgerichte auf Rechtsverletzungen. Er kann jedoch nur angerufen werden, wenn es keine andere Möglichkeit gibt, die Entscheidung anzufechten ([[außerordentliche]] Revision)"}, {"kategorie": "", "text": "Die Verwaltungsgerichte in Österreich haben die Aufgabe, Entscheidungen und Handlungen der Verwaltung auf ihre Rechtmäßigkeit hin zu überprüfen. Dabei entscheiden sie vor allem über:  (i) Beschwerden gegen [[Bescheide]]: Bürger können gegen Verwaltungsakte, wie z.B. Steuerbescheide oder Bauverordnungen, Beschwerde einlegen;  (ii) [[Maßnahmenbeschwerden]]: Wenn sich jemand durch das Verhalten einer Behörde oder deren Organe in seinen Rechten verletzt fühlt, kann er eine Maßnahmenbeschwerde einreichen;  (iii) [[Säumnisbeschwerden]]: Werden Behördenentscheidungen nicht innerhalb einer angemessenen Frist getroffen, kann eine Säumnisbeschwerde eingelegt werden"}, {"kategorie": "", "text": "Die Verwaltungsgerichte gewährleisten, dass staatliche und behördliche Entscheidungen rechtsstaatlich kontrolliert werden. Sie spielen eine zentrale Rolle im österreichischen Rechtssystem, indem sie die Verwaltung zur Einhaltung der Gesetze verpflichten und den Bürgern ein Instrument bieten, ihre Rechte gegenüber der öffentlichen Verwaltung zu wahren."}]'::jsonb, ''),
  ('saeumnisbeschweade', 'Säumnisbeschweade', '', '', '', '', 'Säumnisbeschwerde', '[{"kategorie": "jur.", "text": "\"Rechtsmittel im österreichischen Verwaltungsrecht, das einem Bürger die Möglichkeit gibt, gegen die Untätigkeit einer Behörde vorzugehen\""}, {"kategorie": "", "text": "Sie kommt zum Einsatz, wenn eine Behörde ihrer Pflicht zur Entscheidung innerhalb einer angemessenen Frist nicht nachkommt, also eine sogenannte Säumnis vorliegt"}, {"kategorie": "", "text": "Eine Säumnisbeschwerde kann erhoben werden, wenn folgende Voraussetzungen erfüllt sind:  (i) Pflicht zur Bescheiderlassung: Die Behörde muss verpflichtet sein, über einen bestimmten Antrag oder eine bestimmte Angelegenheit einen Bescheid zu erlassen;  (ii) Fristablauf: Die gesetzlich vorgesehene Entscheidungsfrist (in der Regel sechs Monate) ist abgelaufen, ohne dass die Behörde eine Entscheidung getroffen hat. Es kann auch eine kürzere Frist gelten, wenn ein Gesetz dies ausdrücklich vorsieht;  (iii) Antragsteller: Nur die Person oder Partei, die ein berechtigtes Interesse an der Entscheidung hat und die den Antrag gestellt hat, kann die Säumnisbeschwerde einlegen"}, {"kategorie": "", "text": "Zuständigkeit: Die Säumnisbeschwerde ist an das zuständige [[Verwaltungsgericht]] zu richten (in den meisten Fällen das [[Landesverwaltungsgericht]] oder das [[Bundesverwaltungsgericht]])"}, {"kategorie": "", "text": "Frist und Form: Die Säumnisbeschwerde kann nach Ablauf der vorgesehenen Frist jederzeit erhoben werden, muss aber die notwendige Form und den Inhalt erfüllen, indem sie die betroffene Behörde und den beantragten Bescheid klar benennt"}, {"kategorie": "", "text": "Verfahren der Säumnisbeschwerde:  Das Verwaltungsgericht prüft im Säumnisbeschwerdeverfahren, ob die Behörde tatsächlich säumig ist und ob es Gründe gibt, die Säumnis zu rechtfertigen (z.B. komplexe Sachverhalte, die eine längere Bearbeitung erfordern). Kommt das Gericht zum Ergebnis, dass die Behörde ihre Entscheidungspflicht verletzt hat, kann es die Behörde entweder zur Bescheiderlassung auffordern oder selbst einen Bescheid anstelle der Behörde erlassen"}, {"kategorie": "", "text": "Die Säumnisbeschwerde schützt [[Bürger]] und Unternehmen vor unangemessenen Verzögerungen durch Behörden und gewährleistet, dass Verwaltungsverfahren in einem angemessenen Zeitrahmen abgeschlossen werden. Sie ist ein wichtiges Instrument zur Durchsetzung des Rechtsstaatsprinzips und verhindert, dass die Rechte der Antragsteller durch behördliche Untätigkeit beeinträchtigt werden."}]'::jsonb, ''),
  ('fristsetzungsauntroog', 'Fristsetzungsauntroog', '', '', '', '', 'Fristsetzungsantrag', '[{"kategorie": "jur.", "text": "\"Rechtsmittel im österreichischen Zivilprozessrecht, das einer Partei ermöglicht, das Verfahren zu beschleunigen, wenn ein Gericht eine Entscheidung nicht innerhalb einer angemessenen Frist getroffen hat\""}, {"kategorie": "", "text": "Der Fristsetzungsantrag ist speziell dafür vorgesehen, Verfahrensverzögerungen durch gerichtliche Untätigkeit zu verhindern und sicherzustellen, dass der Prozess ohne ungebührliche Verzögerung fortgeführt wird"}, {"kategorie": "", "text": "Ein Fristsetzungsantrag kann gestellt werden, wenn die folgenden Bedingungen erfüllt sind:  (i) Verfahrensverzögerung: Das Gericht hat eine Entscheidung oder Verfahrenshandlung nicht in einer angemessenen Zeit vorgenommen. Diese Verzögerung darf nicht auf das Verhalten der antragstellenden Partei selbst zurückzuführen sein;  (ii) Ermüdung anderer Möglichkeiten: In der Regel muss die Partei zunächst versuchen, das Verfahren durch andere Mittel (z.B. durch Erinnerungen) voranzubringen, bevor sie einen Fristsetzungsantrag stellt;  (iii) Zuständigkeit: Der Fristsetzungsantrag wird beim zuständigen übergeordneten Gericht eingebracht, z.B., beim [[Oberlandesgericht]], wenn die Verzögerung bei einem Bezirks- oder Landesgericht auftritt;  (iv) Inhalt und Form: Der Antrag muss schriftlich eingebracht werden und sollte die verzögerte Verfahrenshandlung, den bisherigen Verfahrensstand und die Begründung der Verzögerung enthalten"}, {"kategorie": "", "text": "Wenn ein Fristsetzungsantrag gestellt wird, prüft das übergeordnete Gericht, ob tatsächlich eine unangemessene Verfahrensverzögerung vorliegt. Sollte dies der Fall sein, kann das Gericht eine Frist für die Handlung setzen: Das übergeordnete Gericht weist das zuständige Gericht an, die ausstehende Handlung (z.B. eine Entscheidung, eine Ladung zur Verhandlung) innerhalb einer festgelegten Frist vorzunehmen"}, {"kategorie": "", "text": "Sollte das Gericht die Verzögerung als gerechtfertigt ansehen, wird der Fristsetzungsantrag abgelehnt"}, {"kategorie": "", "text": "Der Fristsetzungsantrag ist ein wichtiges Instrument, um die Verfahrensdauer in zivilrechtlichen Verfahren zu begrenzen und die Rechtsschutzgarantie der Parteien zu sichern. Er stärkt das Vertrauen der Bürger in die Justiz und sichert das Grundrecht auf ein zügiges Verfahren, indem er unnötige Verzögerungen im Gerichtsverfahren verhindern soll."}]'::jsonb, ''),
  ('vawoitungsgerichtshof', 'Vawoitungsgerichtshof', '', '', '', '', 'Verwaltungsgerichtshof', '[{"kategorie": "", "text": "Der Verwaltungsgerichtshof ist eine zentrale Institution im österreichischen Rechtssystem und sichert die [[Rechtsstaatlichkeit]] und [[Rechtssicherheit]] im Bereich des [[öffentlichen]] Rechts, indem er die Verwaltung zur Einhaltung der [[Gesetze]] verpflichtet"}, {"kategorie": "", "text": "Der Verwaltungsgerichtshof ist hauptsächlich für folgende Aufgaben zuständig:  (i) Überprüfung von Entscheidungen der Verwaltungsgerichte: Der VwGH prüft Entscheidungen der Verwaltungsgerichte erster Instanz ([[Landesverwaltungsgerichte]], [[Bundesverwaltungsgericht]], [[Bundesfinanzgericht]]) auf mögliche Rechtsverletzungen;  (ii) Rechtsprechung zu grundsätzlichen Rechtsfragen: Der VwGH klärt in seiner Rechtsprechung grundlegende Fragen des [[Verwaltungsrechts]] und stellt sicher, dass Verwaltungsentscheidungen im Einklang mit den [[Gesetzen]] und der [[Verfassung]] stehen;  (iii) Sicherung der einheitlichen Rechtsanwendung: Der VwGH sorgt dafür, dass ähnliche Fälle einheitlich entschieden werden und trägt so zur [[Rechtssicherheit]] bei;  (iv) Beschwerdeinstanz bei Verletzung subjektiver Rechte: [[Bürger]] und Unternehmen können eine Beschwerde beim VwGH einlegen, wenn sie der Meinung sind, dass eine Entscheidung eines Verwaltungsgerichts ihre subjektiven Rechte verletzt"}, {"kategorie": "", "text": "Die wichtigsten Verfahrensarten vor dem VwGH sind:  (i) Revision: Die Revision ist das hauptsächliche [[Rechtsmittel]] gegen Entscheidungen der Verwaltungsgerichte. Es gibt zwei Arten: (A) Ordentliche Revision: Ist zulässig, wenn das Verwaltungsgericht von einer grundsätzlichen Rechtsfrage betroffen ist und die Entscheidung von allgemeiner Bedeutung ist;  (B) Außerordentliche Revision: Diese wird eingebracht, wenn die ordentliche Revision ausgeschlossen ist. Der VwGH prüft dann, ob eine grundsätzliche Rechtsfrage vorliegt und ob die Revision dennoch zugelassen wird"}, {"kategorie": "", "text": "[[Säumnisbeschwerde]]: Wenn ein Verwaltungsgericht untätig bleibt und eine Entscheidung nicht in angemessener Frist trifft, können Bürger eine Säumnisbeschwerde an den VwGH richten"}, {"kategorie": "", "text": "Der Verwaltungsgerichtshof hat seinen Sitz in Wien und ist in mehrere Senate aufgeteilt, die jeweils für verschiedene Fachgebiete des Verwaltungsrechts zuständig sind. Die Richterinnen und Richter des VwGH sind unabhängig und nur der Verfassung und den Gesetzen unterworfen. Die Präsidentin oder der Präsident des VwGH leitet das Gericht und repräsentiert es nach außen"}, {"kategorie": "", "text": "Der VwGH spielt eine zentrale Rolle im österreichischen Verwaltungsrechtssystem, da er die letzte Instanz zur Überprüfung von Verwaltungsentscheidungen darstellt. Er sichert den [[Rechtsstaat]], indem er Verwaltungshandeln kontrolliert und dafür sorgt, dass Bürgerrechte gegenüber dem [[Staat]] geschützt werden. Seine [[Urteile]] prägen das [[Verwaltungsrecht]] nachhaltig und dienen oft als Rechtsgrundlage für die Verwaltungspraxis."}]'::jsonb, ''),
  ('vawoitungsrecht', 'Vawoitungsrecht', '', '', '', '', 'Verwaltungsrecht', '[{"kategorie": "jur.", "text": "\"jener Teil des öffentlichen Rechts, der die Rechtsbeziehungen zwischen dem [[Staat]] (bzw. seinen Verwaltungsorganen) und den [[Bürgern]] regelt\""}, {"kategorie": "", "text": "Das Verwaltungsrecht umfasst sämtliche [[Gesetze]] und Vorschriften, die das Handeln von [[Behörden]] und öffentlichen Einrichtungen steuern, und stellt sicher, dass die Verwaltung im Einklang mit den Grundsätzen des [[Rechtsstaats]] handelt"}, {"kategorie": "", "text": "Das Verwaltungsrecht ist vielfältig und regelt zahlreiche Aspekte des täglichen Lebens. Zu den wichtigsten Bereichen gehören:  (i) Allgemeines Verwaltungsrecht: Grundlegende Prinzipien und Vorschriften, die für das Handeln der [[Verwaltung]] allgemein gelten. Dazu gehören Bestimmungen über das Verwaltungsverfahren, die Behördenorganisation und den [[Rechtsschutz]];  (ii) Besonderes Verwaltungsrecht: Spezifische Rechtsbereiche, in denen der Staat seine Verwaltungsaufgaben wahrnimmt. Dazu zählen: (A) Baurecht: Regelt Genehmigungen und Vorschriften für Bauvorhaben;  (B) Gewerberecht: Bestimmt die Voraussetzungen und Rahmenbedingungen für die Ausübung von Gewerben;  (C) Polizei- und Sicherheitsrecht: Legt fest, wie öffentliche Sicherheit gewährleistet wird, z.B. durch Polizei oder andere Sicherheitsorgane;  (D) Umweltrecht: Vorschriften zum Schutz der Umwelt und zur Regulierung von Umweltbelastungen;  (E) Verkehrsrecht: Regeln für Straßenverkehr, Führerscheine und Verkehrssicherheit;  (F) Sozialrecht: Bestimmungen zur sozialen Absicherung und staatlichen Unterstützung"}, {"kategorie": "", "text": "Verfassungsrechtliche Grundlagen: Das Verwaltungsrecht basiert auf den Grundsätzen der österreichischen [[Verfassung]], insbesondere auf den Prinzipien des [[Rechtsstaats]], der Gleichheit und der Verhältnismäßigkeit. Das bedeutet, dass Verwaltungshandeln immer rechtlich gebunden und verhältnismäßig sein muss"}, {"kategorie": "", "text": "Ein zentrales Element des Verwaltungsrechts ist das Verwaltungsverfahren, das in den Verwaltungsverfahrensgesetzen (AVG) geregelt ist. Hierbei handelt es sich um formelle Abläufe, die sicherstellen, dass die Verwaltung einheitlich, fair und gesetzeskonform entscheidet"}, {"kategorie": "", "text": "Wichtige Instrumente des Rechtsschutzes im Verwaltungsrecht umfassen:  (i) Beschwerdeverfahren vor Verwaltungsgerichten: Bürger können gegen behördliche Entscheidungen Beschwerde einlegen, und die [[Verwaltungsgerichte]] prüfen diese auf Rechtswidrigkeit;  (ii) Revision zum [[Verwaltungsgerichtshof]] (VwGH): Gegen Entscheidungen der Verwaltungsgerichte kann in bestimmten Fällen Revision zum VwGH erhoben werden;  (iii) Verfassungsgerichtshof (VfGH): Dieser ist zuständig, wenn Verwaltungsakte gegen verfassungsrechtlich garantierte Rechte verstoßen"}, {"kategorie": "", "text": "Das Verwaltungsrecht folgt mehreren grundlegenden Prinzipien: (i) [[Legalitätsprinzip]]: Verwaltungshandeln muss immer auf einer gesetzlichen Grundlage beruhen;  (ii) [[Verhältnismäßigkeitsprinzip]]: Eingriffe der Verwaltung müssen geeignet, erforderlich und angemessen sein;  (iii) [[Gleichheitsgrundsatz]]: Alle Bürger sind vor dem Gesetz gleich zu behandeln;  (iv) [[Recht]] auf Gehör: Betroffene haben das Recht, vor Entscheidungen der Verwaltung angehört zu werden"}, {"kategorie": "", "text": "Das Verwaltungsrecht stellt sicher, dass die Verwaltung ihre Aufgaben im Interesse des Gemeinwohls erfüllt und dabei die Rechte der Bürger respektiert. Es schafft klare Regeln für das Handeln staatlicher Organe und gewährleistet [[Rechtsstaatlichkeit]], Transparenz und Nachvollziehbarkeit im Verwaltungshandeln. Dadurch wird das Vertrauen der Bürger in die öffentliche Verwaltung gestärkt und die Kontrolle staatlicher Macht abgesichert."}]'::jsonb, ''),
  ('rechtsschdoodsprinzip', 'Rechtsschdoodsprinzip', '', '', '', '', 'Rechtsstaatsprinzip', '[{"kategorie": "jur.", "text": "\"zentraler Grundsatz der österreichischen [[Bundesverfassung]], was bedeutet, dass der [[Staat]] an das [[Gesetz]] gebunden ist und sein Handeln nach Recht und Gesetz ausrichten muss\""}, {"kategorie": "", "text": "Das Rechtsstaatsprinzip stellt sicher, dass die Ausübung staatlicher Macht nachprüfbar, transparent und kontrollierbar ist und dass die Rechte der Bürger geschützt werden"}, {"kategorie": "", "text": "Das Rechtsstaatsprinzip umfasst mehrere zentrale Elemente, die sicherstellen, dass staatliches Handeln rechtlich gebunden und gerecht ist:  (i) Gesetzmäßigkeit der Verwaltung ([[Legalitätsprinzip]]): Alle Handlungen der Verwaltung müssen eine gesetzliche Grundlage haben. Dies bedeutet, dass Behörden und Verwaltungsorgane nur aufgrund von Gesetzen handeln dürfen. Das Legalitätsprinzip ist in Artikel 18 der österreichischen Bundesverfassung festgeschrieben und schützt die Bürger vor willkürlichem staatlichem Eingriff;  (ii) [[Rechtsschutz]] und Zugang zu Gerichten: Das Rechtsstaatsprinzip gewährleistet, dass Bürger ihre Rechte gegenüber dem Staat durchsetzen können. Dafür gibt es unabhängige [[Gerichte]], die Verwaltungs- und Justizentscheidungen überprüfen und gegebenenfalls korrigieren können, etwa durch [[Verwaltungsgerichte]], den [[Verwaltungsgerichtshof]] und den [[Verfassungsgerichtshof]]"}, {"kategorie": "", "text": "[[Gewaltenteilung]]: Das Rechtsstaatsprinzip beinhaltet die Trennung der staatlichen Gewalt in [[Legislative]] (Gesetzgebung), [[Exekutive]] (Verwaltung) und [[Judikative]] (Rechtsprechung). Dadurch wird verhindert, dass eine Machtkonzentration entsteht und dass einzelne Staatsorgane ihre Kompetenzen überschreiten"}, {"kategorie": "", "text": "[[Rechtssicherheit]] und Bestimmtheit: Die Gesetze müssen klar formuliert und für die Bürger verständlich sein. Rechtssicherheit bedeutet, dass Bürger wissen, welche rechtlichen Konsequenzen ihr Handeln haben kann, und darauf vertrauen können, dass das Recht beständig und nachvollziehbar angewandt wird"}, {"kategorie": "", "text": "[[Verhältnismäßigkeitsprinzip]]: Alle staatlichen Eingriffe in die Rechte der [[Bürger]] müssen verhältnismäßig sein. Das bedeutet, dass sie einem legitimen Zweck dienen müssen und nicht über das hinausgehen dürfen, was zur Erreichung dieses Zwecks notwendig ist"}, {"kategorie": "", "text": "Schutz der [[Grund-]] und Menschenrechte: Das Rechtsstaatsprinzip schützt die Grund- und Menschenrechte der Bürger. Diese Rechte sind durch die Bundesverfassung, die Europäische Menschenrechtskonvention (EMRK) und das EU-Recht abgesichert und stellen sicher, dass Bürger vor unverhältnismäßigen Eingriffen des Staates geschützt sind."}]'::jsonb, ''),
  ('gleichheitsgrundsotz', 'Gleichheitsgrundsotz', '', '', '', '', 'Gleichheitsgrundsatz', '[{"kategorie": "jur.", "text": "\"verfassungsrechtliches Prinzip in Österreich, das die Gleichbehandlung aller Bürger vor dem Gesetz sicherstellt\""}, {"kategorie": "", "text": "Verankert ist der Grundsatz in Artikel 7 der [[österreichischen]] Bundesverfassung (B-VG) sowie in der [[Europäischen]] Menschenrechtskonvention (EMRK)"}, {"kategorie": "", "text": "Der Gleichheitsgrundsatz verpflichtet den Staat, ohne Willkür zu handeln und keine Person oder Gruppe ungleich zu behandeln, wenn es dafür keinen sachlich gerechtfertigten Grund gibt"}, {"kategorie": "", "text": "Der Gleichheitsgrundsatz umfasst verschiedene wesentliche Elemente:  (i) Gleichheit vor dem Gesetz: Alle Menschen sind vor dem Gesetz gleich und haben einen Anspruch darauf, in vergleichbaren Situationen gleich behandelt zu werden. Dies bezieht sich auf die Rechte und Pflichten, die durch Gesetze und Verordnungen geregelt sind;  (ii) [[Willkürverbot]]: Der Staat darf keine willkürlichen Unterschiede machen. Differenzierungen in der Gesetzgebung oder Verwaltungspraxis müssen immer sachlich begründbar sein. Eine Ungleichbehandlung ist nur dann zulässig, wenn es dafür einen objektiven und vernünftigen Grund gibt, der dem Gemeinwohl dient;  (iii) [[Diskriminierungsverbot]]: Der Gleichheitsgrundsatz enthält auch das Verbot der Diskriminierung, insbesondere in Bezug auf Geschlecht, Abstammung, ethnische Herkunft, Religion oder Weltanschauung. Bestimmte Ungleichbehandlungen, die auf diesen Merkmalen beruhen, sind verfassungsrechtlich unzulässig;  (iv) Verhältnismäßigkeit der Differenzierungen: Wenn der Staat unterschiedliche Regelungen für verschiedene Personengruppen trifft, müssen diese verhältnismäßig sein. Das bedeutet, dass die Maßnahme geeignet, erforderlich und angemessen sein muss, um ein legitimes Ziel zu erreichen"}, {"kategorie": "", "text": "Gleichheitsgrundsatz als subjektives Recht: In Österreich können Bürger den Gleichheitsgrundsatz direkt vor dem [[Verfassungsgerichtshof]] geltend machen. Sie können etwa eine [[Beschwerde]] beim Verfassungsgerichtshof einlegen, wenn sie sich durch ein Gesetz oder eine behördliche Entscheidung diskriminiert oder ungerecht behandelt fühlen"}, {"kategorie": "", "text": "Der Gleichheitsgrundsatz wirkt sowohl auf die Gesetzgebung als auch auf die Verwaltung und Gerichtsbarkeit. Dies bedeutet:  (i) Gesetzgebung: Der Gesetzgeber darf keine Regelungen schaffen, die Personen oder Gruppen ohne sachlichen Grund benachteiligen oder bevorzugen;  (ii) Verwaltung und Gerichte: Verwaltungsbehörden und Gerichte müssen den Gleichheitsgrundsatz in ihren Entscheidungen berücksichtigen und dürfen vergleichbare Fälle nicht ohne sachlichen Grund unterschiedlich behandeln"}, {"kategorie": "", "text": "Der Gleichheitsgrundsatz ist eine wichtige Grundlage für den [[Rechtsstaat]] und die [[Demokratie]] in Österreich. Er sichert den Bürgern das Recht auf eine gerechte und gleiche Behandlung und schützt sie vor Diskriminierung und willkürlicher Ungleichbehandlung durch den Staat. In der Praxis bedeutet dies, dass Gesetze und behördliche Maßnahmen überprüft und gegebenenfalls aufgehoben werden können, wenn sie gegen den Gleichheitsgrundsatz verstoßen."}]'::jsonb, ''),
  ('vahoetnismaessigkeitsprinzip', 'Vahötnismässigkeitsprinzip', '', '', '', '', 'Verhältnismäßigkeitsprinzip', '[{"kategorie": "jur.", "text": "\"zentraler Grundsatz des österreichischen Verfassungsrechts, der sicherstellt, dass staatliche Eingriffe in die Rechte der Bürger angemessen und gerechtfertigt sind\""}, {"kategorie": "", "text": "Dieser Grundsatz verpflichtet den [[Staat]], nur solche Maßnahmen zu ergreifen, die zur Erreichung eines legitimen Ziels erforderlich und geeignet sind und dabei die individuelle Freiheit und Rechte der Bürger so wenig wie möglich einschränken"}, {"kategorie": "", "text": "Das Verhältnismäßigkeitsprinzip ist insbesondere im [[Verwaltungsrecht]] und [[Verfassungsrecht]] von großer Bedeutung und gilt auch im Rahmen der [[Europäischen]] Menschenrechtskonvention (EMRK)"}, {"kategorie": "", "text": "Das Verhältnismäßigkeitsprinzip besteht aus drei wesentlichen Elementen, die stets gemeinsam geprüft werden müssen:  (i) Geeignetheit: Die Maßnahme muss zur Erreichung des legitimen Zwecks geeignet sein, das heißt, sie muss einen sinnvollen Beitrag zur Zielerreichung leisten. Wenn die Maßnahme das Ziel nicht unterstützen kann, ist sie unverhältnismäßig;  (ii) Erforderlichkeit: Die Maßnahme darf nicht weitergehen, als es zur Erreichung des Ziels notwendig ist. Wenn es mildere, gleich wirksame Alternativen gibt, die das Ziel erreichen und gleichzeitig die Rechte der Betroffenen weniger stark einschränken, sind diese Alternativen vorzuziehen;  (iii) Angemessenheit (Verhältnismäßigkeit im engeren Sinn): Das Ausmaß des Eingriffs muss im Verhältnis zum angestrebten Ziel stehen. Dies bedeutet, dass der Nutzen der Maßnahme und das öffentliche Interesse an der Zielerreichung den Nachteil und die Beeinträchtigung für die Betroffenen überwiegen müssen. Ein übermäßiger oder unangemessener Eingriff ist nicht erlaubt"}, {"kategorie": "", "text": "Das Verhältnismäßigkeitsprinzip gilt für alle Formen des staatlichen Handelns und ist in vielen Rechtsgebieten anwendbar, vor allem aber in:  (i) [[Verwaltungsrecht]]: Behörden müssen das Verhältnismäßigkeitsprinzip beachten, wenn sie Eingriffe in die Rechte der Bürger vornehmen, etwa bei Maßnahmen im Sicherheits-, Bau- oder Gewerberecht. Eine behördliche Maßnahme ist nur dann zulässig, wenn sie verhältnismäßig ist;  (ii) [[Verfassungsrecht]]: Das Verhältnismäßigkeitsprinzip schützt die [[Grundrechte]], indem es sicherstellt, dass staatliche Eingriffe in Grundrechte wie die [[Meinungsfreiheit]], die [[Eigentumsfreiheit]] oder die [[persönliche]] Freiheit gerechtfertigt sein müssen. Der Verfassungsgerichtshof überprüft, ob Gesetze und Verordnungen, die in Grundrechte eingreifen, verhältnismäßig sind;  (iii) Strafrecht und Polizeirecht: Auch im Bereich der [[Strafverfolgung]] und der polizeilichen Maßnahmen muss das Verhältnismäßigkeitsprinzip gewahrt bleiben. Beispielsweise dürfen Polizei und Justiz nur solche Maßnahmen wie Durchsuchungen oder Inhaftierungen ergreifen, die verhältnismäßig sind."}]'::jsonb, ''),
  ('eigntumsfreiheit', 'Eigntumsfreiheit', '', '', '', '', 'Eigentumsfreiheit', '[{"kategorie": "jur.", "text": "\"Grundrecht in Österreich, das das Recht auf Eigentum schützt und sicherstellt, dass Bürger über ihr Eigentum frei verfügen und dieses nutzen können\""}, {"kategorie": "", "text": "Die Eigentumsfreiheit ist in Artikel 5 des [[Staatsgrundgesetzes]] über die allgemeinen Rechte der Staatsbürger (StGG) sowie in Artikel 1 des Ersten Zusatzprotokolls zur [[Europäischen]] Menschenrechtskonvention (EMRK) verankert"}, {"kategorie": "", "text": "Die Eigentumsfreiheit gehört zu den wesentlichen [[Grundrechten]] und ist Ausdruck der individuellen Freiheit und Autonomie jedes Einzelnen"}, {"kategorie": "", "text": "Die Eigentumsfreiheit umfasst mehrere zentrale Aspekte:  (i) Schutz des Eigentums: Die Eigentumsfreiheit garantiert den Schutz des Eigentums und verbietet willkürliche oder unverhältnismäßige Eingriffe durch den Staat. Dies betrifft sowohl den Besitz von beweglichen Gütern (z. B. Fahrzeuge, Möbel) als auch von Immobilien (z. B. Grundstücke, Gebäude) und anderen Vermögenswerten;  (ii) Verfügungsfreiheit: Das Recht auf Eigentum umfasst die Freiheit, über das Eigentum zu verfügen, es zu nutzen und es zu veräußern. Eigentümer können mit ihrem Eigentum nach Belieben verfahren, solange sie dabei nicht gegen Gesetze oder Rechte Dritter verstoßen;  (iii) Erwerb von Eigentum: Die Eigentumsfreiheit schützt auch das Recht, Eigentum durch Kauf, Schenkung, Erbschaft oder andere rechtmäßige Mittel zu erwerben"}, {"kategorie": "", "text": "Die Eigentumsfreiheit ist jedoch kein uneingeschränktes Recht und kann in bestimmten Fällen eingeschränkt werden, insbesondere durch das [[öffentliche]] Interesse und die [[Gesetzgebung]]. Diese Einschränkungen müssen jedoch den Grundsätzen der [[Verhältnismäßigkeit]] und Rechtmäßigkeit entsprechen. Beispiele für zulässige Eingriffe sind Enteignungen oder Beschränkungen der Nutzung von Grundstücken zum Wohl der Allgemeinheit. Enteignungen müssen allerdings entschädigt werden, und der Betroffene hat Anspruch auf eine angemessene Entschädigung"}, {"kategorie": "", "text": "Die Eigentumsfreiheit ist ein wesentlicher Bestandteil des [[Rechtsstaats]] und der [[Marktwirtschaft]]. Sie fördert die wirtschaftliche Freiheit und die Eigenverantwortung der Bürger und sichert den Individuen das Recht, ihr Eigentum zu besitzen und zu nutzen, wie sie es wünschen. Gleichzeitig sorgt sie für [[Rechtssicherheit]] und schützt die Bürger vor willkürlichen Eingriffen des Staates"}, {"kategorie": "", "text": "Bürger, die sich durch staatliche Maßnahmen in ihrer Eigentumsfreiheit verletzt fühlen, können sich an die Gerichte wenden, um Schutz zu suchen. Der [[Verfassungsgerichtshof]] kann prüfen, ob staatliche Maßnahmen, die das Eigentum einschränken, mit dem verfassungsrechtlich garantierten Eigentumsrecht vereinbar sind. Zudem bietet die [[Europäische]] Menschenrechtskonvention (EMRK) einen übernationalen [[Rechtsschutz]], sodass Bürger ihre Rechte auch beim [[Europäischen]] Gerichtshof für Menschenrechte geltend machen können."}]'::jsonb, ''),
  ('moakdwiatschoft', 'Moakdwiatschoft', '', '', '', '', 'Marktwirtschaft', '[{"kategorie": "allg.", "text": "\"Wirtschaftssystem, in dem die Produktion und Verteilung von Gütern und Dienstleistungen über Angebot und Nachfrage gesteuert wird\""}, {"kategorie": "", "text": "In einer Marktwirtschaft entscheiden die Individuen und Unternehmen frei, welche Produkte sie herstellen, verkaufen oder kaufen, und wie sie ihre Ressourcen einsetzen. Preise und Mengen der Waren werden auf freien Märkten festgelegt, ohne zentrale Planung durch den Staat"}, {"kategorie": "", "text": "Merkmale der Marktwirtschaft:  (i) Angebot und Nachfrage: Die Preise für Güter und Dienstleistungen werden durch das Zusammenspiel von Angebot und Nachfrage bestimmt. Wenn die Nachfrage nach einem Gut steigt und das Angebot knapp ist, erhöht sich der Preis, und umgekehrt;  (ii) Privateigentum: In einer Marktwirtschaft besitzen und kontrollieren private Individuen und Unternehmen die Produktionsmittel (z.B. Maschinen, Gebäude, Rohstoffe). Privateigentum schafft Anreize für Investitionen und Innovation, da die Eigentümer von ihrem Erfolg profitieren können;  (iii) Gewinnorientierung: Unternehmen streben danach, Gewinne zu erzielen. Sie versuchen, durch effizientes Wirtschaften, Kostensenkungen und Qualitätsverbesserungen ihre Produkte und Dienstleistungen attraktiv zu gestalten;  (iv) Wettbewerb: Unternehmen stehen im Wettbewerb zueinander, was Innovationen fördert und zu einer besseren Auswahl und Qualität der Produkte führt. Der Wettbewerb soll verhindern, dass einzelne Unternehmen zu viel Macht oder Marktanteile gewinnen;  (v) Freie Preisbildung: Preise entstehen durch Angebot und Nachfrage und spiegeln die Knappheit und den Wert von Gütern wider. Diese Preise informieren die Marktteilnehmer über die wirtschaftlichen Bedingungen und leiten die Ressourcenverteilung"}, {"kategorie": "", "text": "Obwohl die Marktwirtschaft auf dem Prinzip des freien Marktes beruht, übernimmt der Staat bestimmte Aufgaben, um die Funktionsfähigkeit des Systems sicherzustellen:  (i) Schutz des Wettbewerbs: Der Staat kann Maßnahmen ergreifen, um Monopole oder Kartelle zu verhindern, die den freien Wettbewerb einschränken;  (ii) Rechtlicher Rahmen: Der Staat stellt durch [[Gesetze]] (z. B. Vertragsrecht, Eigentumsrecht) sicher, dass die Marktakteure ihre Geschäfte rechtssicher abwickeln können;  (iii) Soziale Sicherheit: In einer sozialen Marktwirtschaft sorgt der [[Staat]] für soziale Absicherung (z.B. durch Arbeitslosengeld, Renten) und reguliert den Arbeitsmarkt, um Ungleichheiten abzumildern;  (iv) Umwelt- und Verbraucherschutz: Der Staat kann Vorschriften zum Schutz der Umwelt und der Verbraucher erlassen, um langfristige Schäden zu verhindern, die der Markt alleine nicht lösen könnte"}, {"kategorie": "", "text": "Es gibt verschiedene Formen der Marktwirtschaft, die sich in der Rolle des Staates und in der sozialen Absicherung unterscheiden:  (i) Freie Marktwirtschaft: Der Staat greift kaum ein, und die Marktteilnehmer agieren völlig frei (theoretisches Modell);  (ii) Soziale Marktwirtschaft: Der Staat greift regulierend ein, um soziale Gerechtigkeit und Sicherheit zu fördern. Diese Form ist in Österreich und vielen europäischen Ländern verbreitet."}]'::jsonb, ''),
  ('kartell', 'Kartell', '', '', '', '', 'Kartell', '[{"kategorie": "allg.", "text": "\"Vereinbarung oder Zusammenarbeit zwischen mehreren Unternehmen, die normalerweise im Wettbewerb zueinander stehen\""}, {"kategorie": "", "text": "Ziel eines Kartells ist es, den Wettbewerb einzuschränken oder zu beeinflussen, um gemeinsame wirtschaftliche Vorteile zu erzielen, z.B. durch Preisabsprachen, Mengenbegrenzungen oder die Aufteilung von Märkten"}, {"kategorie": "", "text": "Kartelle verstoßen meist gegen das Prinzip der freien [[Marktwirtschaft]] und sind in vielen Ländern, einschließlich der EU und Österreich, illegal, da sie den freien Wettbewerb behindern und Konsumenten schaden können"}, {"kategorie": "", "text": "Kartelle können in unterschiedlichen Formen auftreten: (i) Preiskartell: Unternehmen vereinbaren gemeinsame Preise oder Preisgrenzen, um den Wettbewerb auf Preisbasis zu verhindern. Das Ziel ist, höhere Preise festzusetzen und dadurch die Gewinne zu maximieren;  (ii) Mengenkartell: Hier einigen sich die Unternehmen auf bestimmte Produktions- oder Verkaufsquoten, um das Angebot zu beschränken und die Preise stabil oder höher zu halten;  (iii) Gebietskartell: Unternehmen teilen sich geografische Märkte auf, sodass jedes Unternehmen in einem bestimmten Gebiet tätig ist und keine Konkurrenz von den anderen Mitgliedern des Kartells befürchten muss;  (iv) Konditionenkartell: Unternehmen stimmen sich über allgemeine Geschäftsbedingungen, Rabatte oder Lieferbedingungen ab, um die Wettbewerbsbedingungen anzugleichen;  (v) Submissionskartell: Hierbei sprechen sich Unternehmen bei öffentlichen Ausschreibungen ab, um sicherzustellen, dass ein bestimmtes Unternehmen den Zuschlag erhält"}, {"kategorie": "", "text": "Kartelle entstehen oft aus dem Bestreben von Unternehmen, den Wettbewerbsdruck zu mindern und dadurch höhere Preise, stabilere Märkte oder größere Marktanteile zu erzielen. Kartellabsprachen können den Unternehmen dabei helfen, Kosten zu sparen und Gewinne zu maximieren, indem sie den Wettbewerb in einem bestimmten Bereich ausschalten oder verringern"}, {"kategorie": "", "text": "In Österreich und der EU sind Kartelle grundsätzlich verboten, da sie den Wettbewerb verzerren und dem Wohl der Verbraucher schaden. Das österreichische Kartellgesetz sowie die EU-Wettbewerbsregeln (Art. 101 des Vertrags über die Arbeitsweise der Europäischen Union, AEUV) verbieten Kartellabsprachen. Die Bundeswettbewerbsbehörde (BWB) in Österreich und die Europäische Kommission überwachen und ahnden Verstöße gegen das Kartellrecht."}]'::jsonb, ''),
  ('monopol', 'Monopol', '', '', '', '', 'Monopol', '[{"kategorie": "jur.", "text": "\"Marktform, bei der ein einzelnes Unternehmen alleiniger Anbieter eines Produkts oder einer Dienstleistung ist und daher den gesamten Markt kontrolliert\""}, {"kategorie": "", "text": "Da es keine Konkurrenz gibt, hat das Monopolunternehmen die Macht, Preise und Mengen weitgehend nach eigenem Ermessen festzulegen. Ein Monopol kann in bestimmten Fällen auch durch staatliche Regulierung entstehen, insbesondere in Bereichen der Grundversorgung"}, {"kategorie": "", "text": "Monopole können auf verschiedene Weise entstehen:  (i) Natürliche Monopole: In manchen Branchen ist es wirtschaftlich effizienter, wenn nur ein Anbieter existiert, da die hohen Fixkosten (z. B. im Bereich der Energieversorgung oder Telekommunikation) für mehrere Anbieter zu teuer wären. In solchen Fällen handelt es sich um natürliche Monopole;  (ii) Staatliche Monopole: Der Staat kann in bestimmten Bereichen das Monopolrecht gewähren, etwa in der Post- oder Wasserversorgung, um eine zuverlässige Grundversorgung sicherzustellen. In vielen Fällen wird das staatliche Monopol jedoch schrittweise liberalisiert;  (iii) Technologische Monopole: Unternehmen, die über ein exklusives Patent oder eine besonders innovative Technologie verfügen, können ein zeitlich begrenztes Monopol ausüben, solange keine Konkurrenten mit vergleichbaren Technologien auf den Markt treten;  (iv) Markenmonopole: Manche Marken besitzen eine solch starke Marktstellung, dass sie wie ein Monopol agieren können, etwa durch besonders begehrte oder exklusive Produkte (z.B. bestimmte Software oder Luxusprodukte)"}, {"kategorie": "", "text": "Da Monopole oft nachteilige Auswirkungen auf den Markt und die Verbraucher haben können, werden sie in vielen Ländern reguliert. In Österreich und der EU überwachen Wettbewerbsbehörden Monopole und greifen ein, wenn Monopolisten ihre Marktmacht missbrauchen, z. B. durch Preisdumping, Marktausschluss oder Benachteiligung der Verbraucher."}]'::jsonb, ''),
  ('kronzeignregelung', 'Kronzeignregelung', '', '', '', '', 'Kronzeugenregelung', '[{"kategorie": "jur.", "text": "\"gesetzliche Möglichkeit im österreichischen Strafrecht, durch die Täter von bestimmten Straftaten eine Strafminderung oder sogar Straffreiheit erlangen können, wenn sie entscheidend zur Aufklärung von schwerwiegenden Straftaten beitragen\""}, {"kategorie": "", "text": "Die Kronzeugenregelung soll die Aufklärung und Verfolgung von organisierten und schwerwiegenden kriminellen Strukturen fördern, indem sie Tätern, die mit den Behörden kooperieren, einen Anreiz bietet"}, {"kategorie": "", "text": "Die Kronzeugenregelung im Strafrecht ist in Österreich im § 41a [[Strafgesetzbuch]] (StGB) geregelt und findet insbesondere bei schwerwiegenden Straftaten Anwendung, die in Verbindung mit organisiertem Verbrechen oder Terrorismus stehen"}, {"kategorie": "", "text": "Damit ein Täter den Status eines Kronzeugen im Strafrecht erlangen kann, müssen folgende Voraussetzungen erfüllt sein:  (i) Aufklärungshilfe: Der Täter muss durch seine Aussage maßgeblich dazu beitragen, dass die Straftat oder die kriminelle Struktur, in der die Tat begangen wurde, aufgedeckt und die Hintermänner oder Mittäter strafrechtlich verfolgt werden können;  (ii) Umfassende Kooperation: Der Täter muss während des gesamten Verfahrens voll kooperieren und alle ihm bekannten Informationen bereitstellen. Unvollständige oder nicht wahrheitsgemäße Aussagen können zum Verlust des Kronzeugenstatus führen;  (iii) \nBedeutung der Informationen: Die Informationen, die der Kronzeuge liefert, müssen eine wesentliche und neue Qualität für die Ermittlungen bieten, welche die Behörden bisher nicht kannten oder selbst hätten aufklären können;  (iv) Selbstanzeige und Reue: In manchen Fällen wird von einem Kronzeugen erwartet, dass er seine eigenen Taten offenlegt und Bereitschaft zeigt, Verantwortung zu übernehmen, sofern diese Taten nicht das zentrale Ziel der Ermittlungen sind;  (v) Zulassung durch die [[Staatsanwaltschaft]]: Die Staatsanwaltschaft entscheidet, ob die Bedingungen erfüllt sind und ob der Kronzeugenstatus gewährt wird"}, {"kategorie": "", "text": "Die Kronzeugenregelung im Strafrecht wird kontrovers diskutiert, da sie Tätern Straffreiheit oder erhebliche Strafminderungen ermöglicht. Kritiker befürchten, dass dies ein „Freikaufen“ für Straftäter darstellen könnte. Zudem besteht die Gefahr, dass Kronzeugen möglicherweise aus eigennützigen Gründen falsche Aussagen machen könnten. Daher unterliegt der Kronzeugenstatus strengen Prüfungen durch die Staatsanwaltschaft und das Gericht, und falsche Angaben können zum Verlust des Status und zur Bestrafung führen."}]'::jsonb, ''),
  ('schdoodsgrundgesetz', 'Schdoodsgrundgesetz', '', '', '', '', 'Staatsgrundgesetz', '[{"kategorie": "", "text": "Offiziell heißt es „Staatsgrundgesetz über die allgemeinen Rechte der Staatsbürger“ und wurde 1867 als Teil der Dezemberverfassung in der [[Habsburgermonarchie]] erlassen. Es ist auch heute noch geltendes Verfassungsrecht und enthält wesentliche Grundrechte, die als Basis der Rechtsordnung in Österreich fungieren und den Schutz der individuellen Freiheit sowie den Schutz vor staatlichem Eingriff garantieren"}, {"kategorie": "", "text": "Das Staatsgrundgesetz legt grundlegende Freiheits- und Gleichheitsrechte fest, die für die Bürger in Österreich gelten. Die wichtigsten enthaltenen Rechte sind:  (i) [[Gleichheit]] vor dem Gesetz: Alle Staatsbürger sind vor dem Gesetz gleich und haben Anspruch auf gleiche Behandlung und Rechte (Art. 2 StGG);  (ii) [[Eigentumsfreiheit]]: Die Freiheit, über das eigene Eigentum zu verfügen und vor willkürlichen Eingriffen des Staates geschützt zu sein (Art. 5 StGG);  (iii) [[Freiheit]] der Person: Schutz vor ungerechtfertigter Freiheitsentziehung und das [[Recht]] auf persönliche Freiheit (Art. 8 StGG);  (iv) [[Meinungs-]], Presse- und Informationsfreiheit: Die Freiheit, Meinungen zu äußern und zu verbreiten, die Pressefreiheit sowie das Recht, sich zu informieren (Art. 13 StGG);  (v) [[Religionsfreiheit]]: Die Freiheit, eine Religion zu wählen, zu praktizieren oder auch keiner Religion anzugehören (Art. 14 StGG);  (vi) [[Versammlungs-]] und Vereinsfreiheit: Das Recht, sich zu versammeln und Vereinigungen zu gründen (Art. 12 StGG);  (vii) [[Unverletzlichkeit]] des Hausrechts: Schutz des Wohnsitzes vor unrechtmäßigen Durchsuchungen und Eingriffen (Art. 9 StGG)"}, {"kategorie": "", "text": "Das Staatsgrundgesetz ist ein zentraler Bestandteil der [[österreichischen]] Bundesverfassung und genießt den Rang eines [[Verfassungsgesetzes]]. Es steht über einfachen Gesetzen und wirkt unmittelbar, d.h., die darin verankerten Grundrechte können von den Bürgern direkt geltend gemacht werden. Derà Verfassungsgerichtshof (VfGH) kann staatliche Maßnahmen und Gesetze auf ihre Vereinbarkeit mit dem Staatsgrundgesetz überprüfen und aufheben, wenn diese gegen die darin festgelegten Rechte verstoßen"}, {"kategorie": "", "text": "Zusätzlich zum Staatsgrundgesetz ist auch die [[Europäische]] Menschenrechtskonvention (EMRK) seit 1964 in Österreich als Verfassungsrecht verankert. Die EMRK ergänzt das Staatsgrundgesetz um weitere Grundrechte und bietet eine europäische Ebene des Grundrechtsschutzes. Beide Dokumente zusammen bilden das Fundament des österreichischen Grundrechtssystems und gewährleisten einen umfassenden Schutz der Menschenrechte."}]'::jsonb, ''),
  ('duachsuchungsbefoeoe', 'Duachsuchungsbeföö', '', '', '', '', 'Durchsuchungsbefehl', '[{"kategorie": "jur.", "text": "\"richterliche Anordnung, die es den Strafverfolgungsbehörden (wie der [[Polizei]]) erlaubt, Wohnungen, Geschäftsräume, Fahrzeuge oder andere geschützte Bereiche einer Person gegen deren Willen zu durchsuchen\""}, {"kategorie": "", "text": "In Österreich dient der Durchsuchungsbefehl dazu, [[Beweismittel]] sicherzustellen, die für die Aufklärung einer Straftat oder zur Festnahme einer Person erforderlich sind"}, {"kategorie": "", "text": "Ein Durchsuchungsbefehl wird nur unter bestimmten gesetzlichen Voraussetzungen erteilt und stellt sicher, dass die Unverletzlichkeit des Hausrechts gewahrt bleibt, indem die Durchsuchung nur durch richterliche Anordnung erfolgt"}, {"kategorie": "", "text": "Voraussetzungen für die Erteilung eines Durchsuchungsbefehls:  (i) Richterliche Anordnung: Ein Durchsuchungsbefehl muss von einem zuständigen [[Gericht]] ausgestellt werden. Nur ein [[Richter]] kann die Durchsuchung anordnen, um die rechtsstaatliche Kontrolle sicherzustellen;  (ii) Verdacht auf eine Straftat: Es muss ein konkreter Verdacht auf eine [[Straftat]] bestehen. Die Durchsuchung darf nur angeordnet werden, wenn es wahrscheinlich ist, dass Beweismittel gefunden werden, die zur Aufklärung der Straftat beitragen können;  (iii) Zweckgebundenheit und Verhältnismäßigkeit: Der Durchsuchungsbefehl muss spezifisch auf die Beweismittel oder Personen abzielen, die gesucht werden. Die Durchsuchung muss verhältnismäßig sein, d. h., sie darf nur durchgeführt werden, wenn keine anderen, weniger belastenden Mittel zur Verfügung stehen;  (iv) Begründung: Der Durchsuchungsbefehl muss schriftlich begründet sein und die Gründe sowie den Gegenstand und Zweck der Durchsuchung konkret benennen, damit die Betroffenen die Notwendigkeit und Rechtmäßigkeit der Maßnahme nachvollziehen können"}, {"kategorie": "", "text": "Die Durchsuchung wird in der Regel von Polizeibeamten durchgeführt. Dabei gelten folgende Grundsätze:  (i) Vorlage des Durchsuchungsbefehls: Die Beamten müssen den Durchsuchungsbefehl den Betroffenen vor der Durchsuchung vorlegen und sie über deren Rechte aufklären;  (ii) Zeugen: Es ist oft erforderlich, dass ein unabhängiger Zeuge bei der Durchsuchung anwesend ist, um sicherzustellen, dass die Durchsuchung rechtmäßig und korrekt abläuft;  (iii) Beschlagnahmung von Beweismitteln: Wenn bei der Durchsuchung Beweismittel gefunden werden, dürfen diese beschlagnahmt werden, um sie für das Strafverfahren zu sichern"}, {"kategorie": "", "text": "In dringenden Fällen, in denen eine richterliche Anordnung nicht rechtzeitig eingeholt werden kann und eine sofortige Durchsuchung notwendig ist, können die Strafverfolgungsbehörden auch ohne Durchsuchungsbefehl handeln. Dies wird als [[Gefahr]] im Verzug bezeichnet und ist beispielsweise bei einer akuten Bedrohungslage zulässig. In solchen Fällen muss die Durchsuchung jedoch nachträglich von einem Gericht überprüft und genehmigt werden"}, {"kategorie": "", "text": "Betroffene haben das Recht, gegen eine Durchsuchung [[Beschwerde]] einzulegen, wenn sie der Meinung sind, dass der Durchsuchungsbefehl unrechtmäßig erteilt wurde oder die Durchsuchung nicht korrekt durchgeführt wurde. Der [[Verfassungsgerichtshof]] oder der [[Oberste]] Gerichtshof können prüfen, ob der Durchsuchungsbefehl im Einklang mit dem [[Gesetz]] und den [[Grundrechten]] der Betroffenen steht."}]'::jsonb, ''),
  ('beweismittl', 'Beweismittl', '', '', '', '', 'Beweismittel', '[{"kategorie": "jur.", "text": "\"jedwede Mittel, die dazu dienen, in einem gerichtlichen oder behördlichen Verfahren Tatsachen festzustellen oder zu beweisen, um den Sachverhalt aufzuklären und die Wahrheit zu ermitteln\""}, {"kategorie": "", "text": "Beweismittel werden sowohl im [[Zivil-]] als auch im Strafrecht eingesetzt und sind entscheidend für die Wahrheitsfindung und die Entscheidungsgrundlage des Gerichts oder der Behörde"}, {"kategorie": "", "text": "In Österreich gibt es verschiedene Arten von Beweismitteln:  (i) [[Zeugen]]: Aussagen von Personen, die den relevanten Sachverhalt beobachtet haben oder über Informationen verfügen, die zur Klärung des Falles beitragen können;  (ii) [[Sachverständige]]: Gutachten von Experten, die fachliche Einschätzungen abgeben und bestimmte Sachverhalte beurteilen können, z. B. medizinische Gutachten oder technische Analysen;  (iii) [[Urkunden]]: Schriftliche Dokumente, die zur Klärung von Tatsachen beitragen, wie Verträge, Rechnungen, Briefe oder Testamente;  (iv) [[Augenschein]]: Dinge, die vom Gericht direkt in Augenschein genommen werden, wie Tatorte, Objekte oder bestimmte physische Beweise. Dazu gehört auch die Besichtigung von Gegenständen oder Orten;  (v) Beweis durch Parteieinvernahme: Aussagen der [[Parteien]] selbst, die zur Aufklärung von Sachverhalten beitragen können, wie etwa die Beschuldigtenvernehmung im [[Strafverfahren]];  (vi) Elektronische Beweismittel: Digitale Daten, wie E-Mails, Textnachrichten, Dateien oder Videoaufnahmen, die im Zuge der Digitalisierung zunehmend an Bedeutung gewinnen"}, {"kategorie": "", "text": "[[Beweislast]]: Die Partei, die eine Tatsache behauptet, trägt die Beweislast, d.h., sie muss den Nachweis erbringen, dass diese Tatsache wahr ist"}, {"kategorie": "", "text": "[[Beweiswürdigung]]: Das Gericht oder die Behörde bewertet die vorgelegten Beweismittel und prüft ihre Glaubwürdigkeit und Zuverlässigkeit. In Österreich gilt der Grundsatz der freien Beweiswürdigung, d.h., das Gericht entscheidet nach eigener Überzeugung, ob es die Beweise als ausreichend ansieht"}, {"kategorie": "", "text": "Nicht alle Beweismittel sind zulässig. Die Beweiserhebung darf die Rechte der Beteiligten nicht verletzen und muss im Einklang mit den rechtlichen Vorschriften stehen. Unzulässige Beweismittel, wie etwa unter Zwang erlangte Aussagen oder Beweise, die gegen das Recht auf Privatsphäre verstoßen, werden nicht in das Verfahren aufgenommen."}]'::jsonb, ''),
  ('religionsfreiheit', 'Religionsfreiheit', '', '', '', '', 'Religionsfreiheit', '[{"kategorie": "jur.", "text": "\"grundlegendes, verfassungsrechtlich geschütztes [[Grundrecht]], das es jedem Menschen erlaubt, seine Religion oder Weltanschauung frei zu wählen, zu praktizieren und zu verbreiten, oder auch keiner Religion anzugehören\""}, {"kategorie": "", "text": "Die Religionsfreiheit ist in mehreren Rechtsquellen verankert, insbesondere in Artikel 14 des [[Staatsgrundgesetzes]] über die allgemeinen Rechte der Staatsbürger (StGG), in der [[Europäischen]] Menschenrechtskonvention (EMRK) sowie in der [[Bundesverfassung]]"}, {"kategorie": "", "text": "Die Religionsfreiheit umfasst mehrere wesentliche Bereiche:  (i) Glaubens- und Gewissensfreiheit: Jeder Mensch hat das Recht, seinen Glauben oder seine Weltanschauung frei zu wählen und zu wechseln. Diese Freiheit umfasst auch die Freiheit, keine Religion zu haben oder atheistisch zu sein;  (ii) Religionsausübungsfreiheit: Die Religionsfreiheit schützt die freie und ungestörte Ausübung des Glaubens. Dazu zählen das Recht auf Gebet, Gottesdienst, religiöse Feste, Rituale und die Bekleidung sowie das Errichten und Betreiben religiöser Einrichtungen und Orte;  (iii) Religionsunterricht und religiöse Erziehung: Eltern haben das Recht, ihre Kinder gemäß ihren religiösen Überzeugungen zu erziehen, und Kinder haben das Recht auf Zugang zum Religionsunterricht. In Österreich ist der Religionsunterricht in öffentlichen Schulen für anerkannte Religionsgemeinschaften verpflichtend, die Teilnahme ist jedoch freiwillig;  (iv) Freiheit zur Religionsgemeinschaft: Die Religionsfreiheit umfasst das Recht, sich in Gemeinschaft mit anderen zu organisieren, religiöse Vereinigungen zu gründen oder sich ihnen anzuschließen, ohne staatliche Behinderung;  (v) Gleichbehandlung der Religionen: Der Staat hat alle Religionsgemeinschaften gleich zu behandeln und darf keine Religion oder Weltanschauung diskriminieren. In Österreich gibt es anerkannte Religionsgemeinschaften, denen bestimmte Rechte, wie der Religionsunterricht in öffentlichen Schulen, gewährt werden"}, {"kategorie": "", "text": "Die Religionsfreiheit ist kein uneingeschränktes Recht und kann eingeschränkt werden, wenn sie andere Grundrechte oder das Gemeinwohl gefährdet. Solche Einschränkungen müssen jedoch verhältnismäßig und gesetzlich begründet sein. Mögliche Einschränkungen bestehen in folgenden Fällen:  (i) Öffentliche Sicherheit und Ordnung: Maßnahmen, die notwendig sind, um die öffentliche Sicherheit, Gesundheit und Moral zu schützen, können das Recht auf Religionsausübung einschränken;  (ii) Schutz der Rechte Dritter: Die Religionsausübung darf nicht die Rechte anderer beeinträchtigen. Zum Beispiel dürfen religiöse Handlungen nicht zur Verletzung der körperlichen Integrität oder der Freiheit anderer führen"}, {"kategorie": "", "text": "In Österreich gibt es anerkannte Religionsgemeinschaften, denen bestimmte Rechte gewährt werden. Dazu zählen unter anderem (i) die katholische Kirche, (ii) die evangelische Kirche, (iii) die islamische Glaubensgemeinschaft, (iv) das Judentum und andere. Diese Religionsgemeinschaften erhalten besondere Rechte, wie etwa das Recht auf Religionsunterricht in öffentlichen Schulen und das Recht zur Erhebung von Kirchensteuern"}, {"kategorie": "", "text": "Daneben gibt es gesetzlich eingetragene religiöse Bekenntnisgemeinschaften, die ebenfalls gewisse Rechte genießen, jedoch weniger weitreichend als die anerkannten Gemeinschaften."}]'::jsonb, ''),
  ('vafossungsrecht', 'Vafossungsrecht', '', '', '', '', 'Verfassungsrecht', '[{"kategorie": "jur.", "text": "\"Gesamtheit der rechtlichen Grundsätze und Normen, die die Organisation und Funktionsweise des [[Staates]], die [[Grundrechte]] der Bürger und das Verhältnis zwischen staatlichen Organen regeln\""}, {"kategorie": "", "text": "Das Verfassungsrecht bildet die oberste rechtliche Grundlage und das Fundament des österreichischen [[Rechtsstaats]]. Die wichtigste Quelle des Verfassungsrechts ist die [[österreichische]] Bundesverfassung (B-VG), die seit 1920 gilt und seither mehrfach reformiert wurde"}, {"kategorie": "", "text": "Das Verfassungsrecht deckt verschiedene zentrale Bereiche ab:  (i) Staatsorganisation: Es regelt die Struktur des Staates, die Aufteilung der [[Staatsgewalt]] und die Kompetenzen der staatlichen Organe. Dazu zählen:  (A) Gewaltenteilung: Die Verfassung teilt die Staatsgewalt in [[Legislative]] (Gesetzgebung), [[Exekutive]] (Verwaltung) und [[Judikative]] (Gerichtsbarkeit) auf, um Machtkonzentration zu verhindern;  (B) [[Föderalismus]]: Österreich ist ein föderaler Staat mit einer Aufteilung der Kompetenzen zwischen Bund und Bundesländern. Die Bundesverfassung regelt diese Kompetenzen und die Beziehung zwischen Bund und Ländern;  (C) Organe der [[Gesetzgebung]] und [[Verwaltung]]: Die Verfassung definiert die Struktur und Funktion der staatlichen Organe wie [[Bundespräsident]], [[Parlament]] ([[Nationalrat]] und [[Bundesrat]]), die [[Landtage]], die [[Regierung]] und die [[Gerichte]];  (D) [[Grundrechte]] und Freiheitsrechte: Die österreichische Verfassung sichert den Bürgern grundlegende Rechte und Freiheiten zu, darunter: Das [[Staatsgrundgesetz]] und die [[Europäische]] Menschenrechtskonvention (EMRK) verankern Grundrechte wie die [[Meinungsfreiheit]], [[Religionsfreiheit]], [[Eigentumsfreiheit]] und das [[Recht]] auf Gleichheit vor dem Gesetz. Diese Grundrechte schützen Bürger vor willkürlichen Eingriffen durch den [[Staat]] und gewährleisten die individuelle Freiheit und Menschenwürde;  (E) Recht auf Mitbestimmung: Die Verfassung sieht Mechanismen zur politischen Teilhabe der Bürger vor, etwa durch [[Wahlen]], [[Volksbegehren]], [[Volksbefragungen]] und [[Volksabstimmungen]]. Diese Instrumente ermöglichen den Bürgern, an der Gesetzgebung und wichtigen politischen Entscheidungen mitzuwirken;  (F) Gesetzgebungsverfahren und [[Rechtsstaatlichkeit]]: Die Verfassung legt die Verfahren fest, nach denen Gesetze erlassen und durchgesetzt werden, und stellt sicher, dass alle staatlichen Maßnahmen an das Gesetz gebunden sind ([[Legalitätsprinzip]])"}, {"kategorie": "", "text": "Der [[Verfassungsgerichtshof]] (VfGH) ist das höchste Organ der Verfassungsgerichtsbarkeit und kann Gesetze, die gegen die Verfassung verstoßen, aufheben"}, {"kategorie": "", "text": "Verfassungsänderungen: Das Verfassungsrecht kann grundsätzlich geändert werden, allerdings unterliegt jede Verfassungsänderung strengen Regeln. Für eine Änderung des Bundes-Verfassungsgesetzes ist eine Zweidrittelmehrheit im [[Nationalrat]] erforderlich, und die Änderung muss ausdrücklich als Verfassungsgesetz gekennzeichnet sein. Einige zentrale Prinzipien der Verfassung, wie das Demokratieprinzip, das Rechtsstaatlichkeitsprinzip und das Bundesstaatsprinzip, können jedoch nur unter besonderen Voraussetzungen geändert werden und genießen einen besonderen Schutz."}]'::jsonb, ''),
  ('bundesvafossungsgesetz', 'Bundesvafossungsgesetz', '', '', '', '', 'Bundesverfassungsgesetz', '[{"kategorie": "", "text": "Es legt die Organisation und Arbeitsweise der wichtigsten Staatsorgane fest, garantiert die [[Grundrechte]] und Freiheitsrechte der [[Bürger]] und bestimmt das Verhältnis zwischen [[Bund]] und [[Ländern]]"}, {"kategorie": "", "text": "Das B-VG ist seit 1920 in Kraft, wurde von [[Hans]] Kelsen entworfen und bildet den Kern der österreichischen Verfassung. Es wurde im Laufe der Jahre mehrfach ergänzt und reformiert"}, {"kategorie": "", "text": "Das B-VG s teilt die [[Staatsgewalt]] in [[Legislative]] (Gesetzgebung), [[Exekutive]] (Verwaltung) und [[Judikative]] (Rechtsprechung) und regelt die Aufgaben und Zuständigkeiten dieser Gewalten. Es definiert die Aufgaben und Zuständigkeiten der wichtigsten Staatsorgane, darunter [[Bundespräsident]], [[Bundesregierung]], [[Nationalrat]], [[Bundesrat]] und [[Landtage]]"}, {"kategorie": "", "text": "Österreich ist ein föderaler Staat mit einer Kompetenzverteilung zwischen dem [[Bund]] und den neun [[Bundesländern]]. Das B-VG legt fest, welche Aufgaben und Gesetzgebungsbefugnisse dem Bund und welche den Ländern zukommen. Die Landesverfassungen der einzelnen Bundesländer müssen im Einklang mit dem B-VG stehen und dürfen diesem nicht widersprechen"}, {"kategorie": "", "text": "Das B-VG enthält einige [[Grundrechte]] und verweist zudem auf weitere Grundrechte, die in anderen Verfassungsgesetzen, wie dem [[Staatsgrundgesetz]] und der [[Europäischen]] Menschenrechtskonvention (EMRK), verankert sind. Zu den geschützten Rechten zählen das Recht auf [[Gleichheit]] vor dem Gesetz, die [[Meinungsfreiheit]], die [[Religionsfreiheit]], die [[persönliche]] Freiheit und der Schutz des Eigentums"}, {"kategorie": "", "text": "Das B-VG definiert die Grundsätze der [[repräsentativen]] Demokratie in Österreich. Die [[Bürger]] wählen ihre Vertreter im [[Nationalrat]], in den [[Landtagen]] und auf kommunaler Ebene. Das B-VG sieht auch direktdemokratische Instrumente wie [[Volksabstimmungen]], [[Volksbegehren]] und [[Volksbefragungen]] vor, die den Bürgern eine direkte Mitbestimmung ermöglichen"}, {"kategorie": "", "text": "Verfassungsgerichtsbarkeit: Das B-VG legt die Grundlagen der Verfassungsgerichtsbarkeit fest. Der [[Verfassungsgerichtshof]] (VfGH) überwacht die Einhaltung der [[Verfassung]] und prüft die Verfassungsmäßigkeit von [[Gesetzen]] und [[Verordnungen]]. Der VfGH kann verfassungswidrige Gesetze aufheben und stellt damit ein zentrales Kontrollorgan zur Sicherstellung der Rechtsstaatlichkeit dar"}, {"kategorie": "", "text": "Das B-VG sichert das [[Rechtsstaatsprinzip]], wonach alle staatlichen Organe an die Gesetze gebunden sind und das staatliche Handeln im Rahmen der Verfassung erfolgen muss. Es verankert das [[Legalitätsprinzip]], das fordert, dass die Verwaltung nur auf gesetzlicher Grundlage handeln darf"}, {"kategorie": "", "text": "Das Bundes-Verfassungsgesetz bildet die rechtliche Grundlage des österreichischen Staatswesens und garantiert die Grundrechte und Freiheitsrechte der Bürger. Es sichert die Stabilität und Funktionsfähigkeit des Staates und gewährleistet, dass das staatliche Handeln im Rahmen demokratischer, rechtsstaatlicher Prinzipien erfolgt. Durch das B-VG werden die Machtverhältnisse im Staat klar geregelt, und die Unabhängigkeit der Gerichte sowie die Bürgerrechte werden geschützt"}, {"kategorie": "", "text": "Das Bundes-Verfassungsgesetz kann grundsätzlich geändert werden, allerdings unterliegt jede Verfassungsänderung strengen Bedingungen: (i) Änderungen bedürfen einer Zweidrittelmehrheit im [[Nationalrat]] sowie der ausdrücklichen Kennzeichnung als Verfassungsgesetz;  (ii) Grundlegende Prinzipien, wie das [[Demokratieprinzip]], das [[Bundesstaatsprinzip]] und das [[Rechtsstaatsprinzip]], gelten als „Grundprinzipien der Verfassung“ und können nur unter sehr besonderen Voraussetzungen geändert werden. Eine Änderung, welche die Grundprinzipien verletzt, würde eine [[Volksabstimmung]] erfordern.\nUnterschied zwischen dem B-VG und anderen Verfassungsgesetzen"}, {"kategorie": "", "text": "Das B-VG ist das zentrale Verfassungsgesetz in Österreich, jedoch besteht das österreichische [[Verfassungsrecht]] aus mehreren Verfassungsgesetzen und Bestimmungen, wie dem [[Staatsgrundgesetz]] von 1867 und der [[Europäischen]] Menschenrechtskonvention (EMRK), die ebenfalls Verfassungsrang haben. Zusammen bilden sie die Verfassungsordnung Österreichs."}]'::jsonb, ''),
  ('demokratiiprinzip', 'Demokratiiprinzip', '', '', '', '', 'Demokratieprinzip', '[{"kategorie": "pol.", "text": "\"fundamentales Grundprinzip der österreichischen [[Bundesverfassung]], das besagt, dass die [[Staatsgewalt]] vom Volk ausgeht\""}, {"kategorie": "", "text": "Es garantiert, dass die [[Bürger]] die oberste Machtquelle sind und an der Gestaltung des Staates aktiv teilnehmen können"}, {"kategorie": "", "text": "Das Demokratieprinzip ist in Artikel 1 des [[Bundes-Verfassungsgesetzes]] (B-VG) verankert und zählt zu den sogenannten „Grundprinzipien der Verfassung“. Es kann nur durch eine [[Volksabstimmung]] geändert werden und bildet das Fundament der österreichischen Staatsordnung"}, {"kategorie": "", "text": "Das Demokratieprinzip in Österreich umfasst mehrere zentrale Aspekte:  (i) [[Repräsentative]] Demokratie: In Österreich werden die politischen Entscheidungen hauptsächlich durch gewählte Vertreter getroffen. Die Bürger wählen in regelmäßigen Wahlen ihre Repräsentanten in den [[Nationalrat]], dieà Landtage und [[Gemeinderäte]]. Diese gewählten Organe sind mit der [[Gesetzgebung]] und Kontrolle der [[Regierung]] betraut;  (ii) [[Volkssouveränität]]: Die Staatsgewalt geht vom Volk aus. Das bedeutet, dass alle staatlichen Organe ihre Legitimation vom Volk erhalten und in seinem Interesse handeln müssen;  (iii) [[Gewaltenteilung]] und [[Rechtsstaatlichkeit]]: Die [[Staatsgewalt]] ist in [[Legislative]], [[Exekutive]] und [[Judikative]] unterteilt, um Machtkonzentration zu verhindern und sicherzustellen, dass staatliches Handeln kontrolliert wird und dem Willen des Volkes entspricht;  (iv) [[Wahlen]] und politische Mitbestimmung: Das Demokratieprinzip umfasst das Recht der Bürger auf freie, gleiche und geheime Wahlen, bei denen sie ihre Repräsentanten wählen können. Zudem garantiert es das aktive und passive [[Wahlrecht]], d. h., das Recht, selbst zu wählen oder gewählt zu werden;  (v) [[Direkte]] Demokratie: Neben der repräsentativen Demokratie existieren auch Instrumente der direkten Demokratie wie [[Volksbegehren]], [[Volksbefragungen]] und [[Volksabstimmungen]], die es den Bürgern ermöglichen, direkt an politischen Entscheidungen teilzunehmen. Diese Instrumente werden in bestimmten Fällen verwendet, etwa bei grundlegenden Verfassungsänderungen oder um Anliegen des Volkes in die politische Debatte einzubringen"}, {"kategorie": "", "text": "Das Demokratieprinzip genießt als Grundprinzip der österreichischen Verfassung besonderen Schutz. Änderungen an Verfassungsgesetzen benötigen eine Zweidrittelmehrheit im Parlament."}]'::jsonb, ''),
  ('bundesschdoodsprinzip', 'Bundesschdoodsprinzip', '', '', '', '', 'Bundesstaatsprinzip', '[{"kategorie": "pol.", "text": "\"grundlegendes Verfassungsprinzip in Österreich, das besagt, dass Österreich ein föderaler Staat ist, der sich aus dem [[Bund]] und den neun [[Bundesländern]] zusammensetzt\""}, {"kategorie": "", "text": "Das Bundesstaatsprinzip ist in der [[österreichischen]] Bundesverfassung verankert und regelt die Verteilung der staatlichen Aufgaben und Kompetenzen zwischen Bund und Ländern, wobei beide Ebenen über eigene Zuständigkeiten und Rechte verfügen"}, {"kategorie": "", "text": "Das Bundesstaatsprinzip zählt zu den „Grundprinzipien“ der Verfassung und kann nur durch eine [[Volksabstimmung]] geändert werden"}, {"kategorie": "", "text": "Wesentliche Inhalte des Bundesstaatsprinzips:  (i) Föderale Struktur: Österreich besteht aus dem Bund und den neun Bundesländern (Burgenland, Kärnten, Niederösterreich, Oberösterreich, Salzburg, Steiermark, Tirol, Vorarlberg und Wien), die jeweils über eigene politische Institutionen und Zuständigkeiten verfügen;  (ii) Kompetenzverteilung: Die [[Bundesverfassung]] legt die Aufteilung der Gesetzgebungs- und Verwaltungskompetenzen zwischen Bund und Ländern fest. Während der Bund für Bereiche wie Außenpolitik, Verteidigung, Zivilrecht und Strafrecht zuständig ist, haben die Länder eigene Zuständigkeiten, etwa im Bauwesen, in der Kulturpolitik und in der Raumordnung. Einige Bereiche unterliegen der geteilten Kompetenz, bei denen der Bund allgemeine Regelungen vorgibt und die Länder Details festlegen;  (iii) Eigene Verfassungen der Länder: Jedes Bundesland hat eine eigene Verfassung, die im Einklang mit der Bundesverfassung steht und das spezifische politische System und die Organisation des jeweiligen Landes regelt. Die Landesverfassungen dürfen jedoch den Grundprinzipien der Bundesverfassung nicht widersprechen;  (iv) [[Landtage]] und [[Landesregierungen]]: Die Bundesländer haben eigene Landtage (Landesparlamente) und Landesregierungen, die für die [[Gesetzgebung]] und [[Verwaltung]] in den Bereichen zuständig sind, die ihnen durch die Bundesverfassung zugewiesen wurden;  (iv) Bundesrat als Vertretung der Länder: Auf Bundesebene sind die Länder durch den [[Bundesrat]] vertreten, eine der beiden Kammern des österreichischen [[Parlaments]]. Der Bundesrat hat die Aufgabe, die Interessen der Länder bei der Gesetzgebung des Bundes zu vertreten. Die Zusammensetzung des Bundesrats richtet sich nach der Bevölkerungszahl der Länder"}, {"kategorie": "", "text": "Das Bundesstaatsprinzip ist als Grundprinzip der Verfassung besonders geschützt und kann nur unter strengen Voraussetzungen geändert werden. Änderungen, die dieses Prinzip betreffen, erfordern: (i) eine Zweidrittelmehrheit im [[Nationalrat]] und im [[Bundesrat]] bzw. (ii) eine [[Volksabstimmung]], falls das Bundesstaatsprinzip direkt oder indirekt geändert werden soll."}]'::jsonb, ''),
  ('vafossungsoadnung', 'Vafossungsoadnung', '', '', '', '', 'Verfassungsordnung', '[{"kategorie": "jur.", "text": "\"alle Rechtsnormen und Grundsätze, welche die staatliche Ordnung, Organisation und [[Grundrechte]] in Österreich regeln\""}, {"kategorie": "", "text": "Die Verfassungsordnung stellt das oberste rechtliche Fundament des Staates dar und definiert die Struktur des politischen Systems, die Rechte und Pflichten der Staatsorgane sowie die Grundrechte der Bürger"}, {"kategorie": "", "text": "Die Verfassungsordnung wird durch mehrere Verfassungsdokumente und -bestimmungen gebildet und umfasst die Grundprinzipien der Verfassung, die als unveränderbar gelten, darunter das [[Demokratieprinzip]], das [[Rechtsstaatsprinzip]], das [[Bundesstaatsprinzip]] und das [[Republikprinzip]]"}, {"kategorie": "", "text": "Elemente der österreichischen Verfassungsordnung: (i) [[Bundes-Verfassungsgesetz]] (B-VG): Das Bundes-Verfassungsgesetz ist das zentrale Verfassungsgesetz Österreichs und regelt die Grundstrukturen des Staates, einschließlich der [[Gewaltenteilung]], der Aufgaben der Staatsorgane, der Gesetzgebungsverfahren und der Verteilung der Kompetenzen zwischen [[Bund]] und [[Ländern]];  (ii) [[Staatsgrundgesetz]] von 1867: Das Staatsgrundgesetz über die allgemeinen Rechte der Staatsbürger enthält wesentliche Grundrechte, wie die [[Gleichheit]] vor dem Gesetz, die [[persönliche]] Freiheit, die [[Eigentumsfreiheit]] und die [[Religionsfreiheit]], die noch immer einen zentralen Bestandteil der Verfassungsordnung bilden;  (iii) [[Europäische]] Menschenrechtskonvention (EMRK): Die Europäische Menschenrechtskonvention, die seit 1964 Verfassungsrang hat, erweitert die Grundrechte der Bürger und ergänzt das Staatsgrundgesetz durch Rechte wie das Recht auf Leben, das Verbot der Folter und das Recht auf ein faires Verfahren;  (iv) Weitere Verfassungsgesetze und -bestimmungen: Die Verfassungsordnung umfasst zusätzlich spezifische Verfassungsgesetze und -bestimmungen, etwa das Finanz-Verfassungsgesetz, das [[Neutralitätsgesetz]] oder das Bundesgesetz über die rechtliche Stellung der Kirchen und Religionsgesellschaften. Diese Gesetze haben Verfassungsrang und ergänzen das B-VG"}, {"kategorie": "", "text": "Die Verfassungsordnung genießt besonderen Schutz. Änderungen an Verfassungsgesetzen und insbesondere an den Grundprinzipien der Verfassung sind nur unter sehr strengen Bedingungen möglich: (i) Zweidrittelmehrheit im [[Nationalrat]]: Verfassungsänderungen erfordern eine qualifizierte Mehrheit von zwei Dritteln im Nationalrat;  (ii) [[Volksabstimmung]] bei Grundprinzipien: Wenn die Grundprinzipien der Verfassung, wie das [[Demokratie-]] oder [[Bundesstaatsprinzip]], verändert werden sollen, muss eine verbindliche Volksabstimmung durchgeführt werden"}, {"kategorie": "", "text": "Die Verfassungsordnung ist das höchste rechtliche Fundament und ein Schutzmechanismus für [[Demokratie]], [[Rechtsstaatlichkeit]] und [[Grundrechte]] in Österreich. Sie sichert die Rechte der Bürger, definiert die Strukturen der Staatsorganisation und gewährleistet eine verlässliche und gerechte Staatsführung. Sie schützt vor willkürlicher Macht und stellt sicher, dass das Handeln des Staates stets den Grundwerten des Gemeinwesens entspricht."}]'::jsonb, ''),
  ('neutralitaetsgesetz', 'Neutralitätsgesetz', '', '', '', '', 'Neutralitätsgesetz', '[{"kategorie": "jur.", "text": "\"österreichisches Verfassungsgesetz, das die [[immerwährende]] Neutralität Österreichs festlegt\""}, {"kategorie": "", "text": "Es wurde am 26. Oktober 1955 vom österreichischen [[Nationalrat]] beschlossen und ist seitdem ein wesentlicher Bestandteil der österreichischen Außenpolitik und [[Verfassungsordnung]]"}, {"kategorie": "", "text": "Mit dem Neutralitätsgesetz verpflichtet sich Österreich, keine militärischen Bündnisse einzugehen und keine fremden Militärstützpunkte auf seinem Staatsgebiet zuzulassen"}, {"kategorie": "", "text": "Das Neutralitätsgesetz ist eine Reaktion auf die politischen Verhältnisse nach dem [[Zweiten]] Weltkrieg und war eine Bedingung für die Wiedererlangung der vollen Souveränität Österreichs nach dem Ende der Besatzung durch die [[Alliierten]] (Sowjetunion, USA, Großbritannien und Frankreich). Mit dem [[Staatsvertrag]] von Wien vom 15. Mai 1955, in dem die Alliierten die Unabhängigkeit Österreichs anerkannten, verpflichtete sich Österreich zur Neutralität, um seine Unabhängigkeit und den Frieden zu sichern"}, {"kategorie": "", "text": "Die wesentlichen Inhalte des Neutralitätsgesetzes sind:  (i) [[Immerwährende]] Neutralität: Österreich erklärt sich für immer neutral und verpflichtet sich, diese Neutralität zu bewahren. Dies bedeutet, dass Österreich keine militärischen Bündnisse eingehen darf und auf die Teilnahme an Kriegen verzichtet, außer zur Selbstverteidigung;  (ii) Verbot ausländischer Militärbasen: Das Gesetz verbietet die Errichtung und den Betrieb fremder Militärbasen auf österreichischem Staatsgebiet, um sicherzustellen, dass Österreich nicht in internationale Konflikte hineingezogen wird;  (iii) Verteidigungspflicht: Österreich verpflichtet sich, die Neutralität im Falle eines Angriffs zu verteidigen. Diese Verpflichtung beinhaltet auch, dass Österreich über ein eigenes Militär (das [[Bundesheer]]) verfügt, um seine Neutralität im Verteidigungsfall zu wahren"}, {"kategorie": "", "text": "Das Neutralitätsgesetz beeinflusst Österreichs Außenpolitik maßgeblich und macht es zu einem neutralen Vermittler in internationalen Konflikten. Die österreichische Neutralität hat das Land zu einem wichtigen Ort für internationale Organisationen gemacht, z.B. die Vereinten Nationen (UNO), die Organisation für Sicherheit und Zusammenarbeit in Europa (OSZE) und die Internationale Atomenergie-Organisation (IAEO), die alle ihren Sitz in Wien haben"}, {"kategorie": "", "text": "Mit dem Beitritt zur Europäischen Union (EU) im Jahr 1995 änderte sich Österreichs Rolle und Interpretation der Neutralität teilweise. Die EU fordert von ihren Mitgliedsstaaten eine gewisse Zusammenarbeit in der Außen- und Sicherheitspolitik. Österreich bleibt jedoch neutral in Bezug auf militärische Bündnisse und bewahrt sich die Möglichkeit, im Falle von kriegerischen Konflikten neutral zu bleiben. Das Neutralitätsgesetz bleibt weiterhin Teil der [[Verfassungsordnung]], und Österreich interpretiert seine Neutralität in Übereinstimmung mit den Verpflichtungen aus der EU-Mitgliedschaft."}]'::jsonb, ''),
  ('voikssouveraenitaet', 'Voikssouveränität', '', '', '', '', 'Volkssouveränität', '[{"kategorie": "pol.", "text": "\"zentrales Prinzip der [[Demokratie]], welches besagt, dass die oberste Gewalt im Staat vom [[Volk]] ausgeht\""}, {"kategorie": "", "text": "Dies bedeutet, dass die [[Bürger]] die höchste Autorität im Staat darstellen und dass alle [[Staatsgewalt]] letztlich auf ihren Willen zurückzuführen ist"}, {"kategorie": "", "text": "In einer Demokratie ist das Volk der Souverän, und alle staatlichen Institutionen und Organe handeln in seinem Namen und auf Grundlage seines Willens"}, {"kategorie": "", "text": "Elemente der Volkssouveränität: (i) [[Repräsentative]] Demokratie: Die Bürger delegieren ihre Macht durch Wahlen an gewählte Vertreter, die im [[Parlament]] und in anderen politischen Ämtern die [[Gesetzgebung]] und Staatsführung übernehmen. Diese Vertreter sind dem Volk gegenüber rechenschaftspflichtig und haben die Aufgabe, im Interesse der Bürger zu handeln;  (ii) [[Direkte]] Demokratie: Neben der repräsentativen Demokratie existieren auch Instrumente der direkten Demokratie, wie [[Volksbegehren]], [[Volksabstimmungen]] und [[Volksbefragungen]], die den Bürgern direkte Mitbestimmung in politischen Entscheidungen ermöglichen. Diese Instrumente ergänzen das Prinzip der Volkssouveränität und stellen sicher, dass die Bürger nicht nur indirekt, sondern in bestimmten Fällen auch unmittelbar über staatliche Angelegenheiten entscheiden können;  (iii) Grundsatz der politischen Gleichheit: Die Volkssouveränität setzt voraus, dass alle Bürger gleichberechtigt an der politischen Willensbildung teilnehmen können. Jeder Bürger hat das gleiche [[Wahlrecht]] und die gleichen Möglichkeiten zur politischen Mitbestimmung, unabhängig von Geschlecht, Herkunft oder sozialem Status;  (iv) Wahlen als Ausdruck der Volkssouveränität: Freie, gleiche und geheime Wahlen sind der zentrale Mechanismus, durch den die Volkssouveränität verwirklicht wird. Durch die Wahlen wählen die Bürger ihre Repräsentanten und bestimmen so die Zusammensetzung der politischen Organe und die Richtung der Politik"}, {"kategorie": "", "text": "In Österreich ist das Prinzip der Volkssouveränität fest in der Bundesverfassung verankert. Artikel 1 des [[Bundes-Verfassungsgesetzes]] (B-VG) lautet: „Österreich ist eine demokratische Republik. Ihr Recht geht vom Volk aus.“ Dies bedeutet, dass alle staatlichen Organe, Entscheidungen und Gesetze auf der Grundlage des Volkswillens legitimiert sind."}]'::jsonb, ''),
  ('rechtsschutz', 'Rechtsschutz', '', '', '', '', 'Rechtsschutz', '[{"kategorie": "jur.", "text": "\"die Gesamtheit aller Möglichkeiten und Mittel, welche den Bürgern zur Verfügung stehen, um ihre Rechte gegenüber dem Staat oder anderen Personen zu verteidigen, zu schützen und durchzusetzen\""}, {"kategorie": "", "text": "Der Rechtsschutz ist ein grundlegendes Element des [[Rechtsstaatsprinzips]] und gewährleistet, dass jeder Zugang zu einer unabhängigen gerichtlichen oder behördlichen Überprüfung seiner Anliegen hat"}, {"kategorie": "", "text": "Der Rechtsschutz garantiert, dass staatliche und private Entscheidungen auf ihre Rechtmäßigkeit und Fairness überprüft werden können, d.h. er schützt die Bürger vor willkürlichen Eingriffen"}, {"kategorie": "", "text": "Elemente des Rechtsschutzes in Österreich:  (i) Verfassungsgerichtlicher Rechtsschutz: Der [[Verfassungsgerichtshof]] (VfGH) überprüft die Verfassungsmäßigkeit von Gesetzen und schützt die Grundrechte der Bürger. Er kann verfassungswidrige Gesetze aufheben und staatliche Entscheidungen auf Grundrechtsverstöße prüfen;  (ii) Verwaltungsgerichtlicher Rechtsschutz: Die Verwaltungsgerichte ([[Bundesverwaltungsgericht]], [[Landesverwaltungsgerichte]]) bieten Rechtsschutz gegen Entscheidungen der Verwaltung. Sie prüfen Verwaltungsakte, wie [[Bescheide]] oder [[Verordnungen]], auf ihre Gesetzmäßigkeit und können unrechtmäßige Akte aufheben;  (iii) Ordentliche Gerichtsbarkeit: Die ordentlichen Gerichte, wie [[Bezirksgerichte]] und [[Landesgerichte]], bieten Rechtsschutz im Bereich des [[Zivil-]] und [[Strafrechts]]. Sie sind für private Rechtsstreitigkeiten (z. B. Vertragsrecht, Schadenersatz) und Strafverfahren zuständig;  (iv) [[Instanzenzug]]: Der österreichische Rechtsweg sieht meist mehrere Instanzen vor, in denen eine Entscheidung überprüft werden kann. Dadurch haben Betroffene die Möglichkeit, eine Entscheidung von höheren Gerichten prüfen zu lassen. Je nach Bereich kann dies bis zum [[Obersten]] Gerichtshof oder den [[Verfassungsgerichtshof]] und [[Verwaltungsgerichtshof]] gehen"}, {"kategorie": "", "text": "Die Bürger haben das [[Recht]] auf ein faires und öffentliches Verfahren, in dem sie angehört werden und Einsicht in die Akten erhalten. Dieses Recht ist durch die [[Europäische]] Menschenrechtskonvention (EMRK) garantiert und beinhaltet die Möglichkeit, sich rechtlich vertreten zu lassen und [[Rechtsmittel]] gegen Entscheidungen einzulegen"}, {"kategorie": "", "text": "Der Staat ist verpflichtet, den Bürgern effektiven Rechtsschutz zu bieten, d. h., der Zugang zu Rechtsmitteln darf nicht unverhältnismäßig erschwert werden. Der Grundrechtsschutz stellt sicher, dass auch die [[Grundrechte]] (z. B. Gleichheit, Eigentum, persönliche Freiheit) wirksam geschützt werden und Verstöße gegen Grundrechte angefochten werden können"}, {"kategorie": "", "text": "Falls der nationale Rechtsschutz in Österreich ausgeschöpft ist und ein Grundrechtsverstoß vermutet wird, können sich Bürger an den [[Europäischen]] Gerichtshof für Menschenrechte (EGMR) wenden. Der EGMR bietet überstaatlichen Rechtsschutz und prüft Verstöße gegen die [[Europäische]] Menschenrechtskonvention"}, {"kategorie": "", "text": "Ombudseinrichtungen und Bürgeranwälte: Neben gerichtlichen Verfahren bieten auch Ombudseinrichtungen (z. B. die [[Volksanwaltschaft]]) Unterstützung und Beratung für Bürger, die sich durch staatliche Maßnahmen beeinträchtigt fühlen. Diese Einrichtungen überprüfen Behördenentscheidungen und können Vorschläge zur Beseitigung von Missständen machen."}]'::jsonb, ''),
  ('ombudsschdoeoen', 'Ombudsschdöön', '', '', '', '', 'Ombudsstellen', '[{"kategorie": "pol.", "text": "\"unabhängige Stellen, die Bürgern helfen, Missstände in der Verwaltung und Verstöße gegen Bürgerrechte zu überprüfen und gegebenenfalls zu beheben\""}, {"kategorie": "", "text": "Diese Einrichtungen agieren als Vermittler zwischen [[Bürgern]] und [[Behörden]] und sorgen für Transparenz und Fairness in der [[Verwaltung]]. Sie nehmen Beschwerden von Bürgern entgegen, die sich von einer Behörde ungerecht behandelt fühlen oder Missstände in der öffentlichen Verwaltung vermuten, und unterstützen dabei, diese Beschwerden zu klären"}, {"kategorie": "", "text": "Die zentrale Ombudseinrichtung in Österreich ist die [[Volksanwaltschaft]]. Sie wurde 1977 gegründet und ist in der [[österreichischen]] Bundesverfassung verankert. Die Volksanwaltschaft ist unabhängig und arbeitet als Kontrollinstanz für die öffentliche Verwaltung. Sie überprüft Verwaltungsakte und Maßnahmen der Verwaltung auf Rechtmäßigkeit und kümmert sich um den Schutz und die Durchsetzung der Bürgerrechte"}, {"kategorie": "", "text": "Neben der Volksanwaltschaft gibt es in Österreich noch andere Ombudseinrichtungen und spezialisierte Anlaufstellen für bestimmte Bereiche:  (i) [[Kinder-]] und Jugendanwaltschaften: Jedes österreichische Bundesland hat eine Kinder- und Jugendanwaltschaft, die sich für die Rechte und den Schutz von Kindern und Jugendlichen einsetzt und Beschwerden oder Anliegen von Kindern, Jugendlichen und deren Eltern bearbeitet;  (ii) [[Gleichbehandlungsanwaltschaft]]: Die Gleichbehandlungsanwaltschaft setzt sich gegen Diskriminierung am Arbeitsplatz oder in anderen Lebensbereichen ein und unterstützt Betroffene bei der Durchsetzung ihres Anspruchs auf Gleichbehandlung;  (iii) [[Patientenanwaltschaften]]: In den Bundesländern gibt es Patientenanwaltschaften, die Bürger bei Anliegen und Beschwerden im Gesundheitsbereich unterstützen und bei Konflikten mit Gesundheitseinrichtungen vermitteln"}, {"kategorie": "", "text": "Ombudseinrichtungen spielen eine zentrale Rolle im österreichischen Rechtsschutzsystem, da sie den Bürgern einen einfachen und kostenlosen Zugang zu Rechtsbeistand und Beratung bieten. Sie fördern das Vertrauen in die öffentliche Verwaltung, indem sie Missstände transparent machen und zur fairen Behandlung der Bürger beitragen. Obwohl ihre Empfehlungen nicht bindend sind, sorgen sie durch ihre Prüf- und Kontrollfunktion für die Einhaltung von Rechtsstaatlichkeit und Bürgerrechten."}]'::jsonb, ''),
  ('ombudseinrichtungan', 'Ombudseinrichtungan', '', '', '', '', 'Ombudseinrichtungen', '[{"kategorie": "pol.", "text": "\"unabhängige Stellen, die Bürgern helfen, Missstände in der Verwaltung und Verstöße gegen Bürgerrechte zu überprüfen und gegebenenfalls zu beheben\""}, {"kategorie": "", "text": "Diese Einrichtungen agieren als Vermittler zwischen [[Bürgern]] und [[Behörden]] und sorgen für Transparenz und Fairness in der [[Verwaltung]]. Sie nehmen Beschwerden von Bürgern entgegen, die sich von einer Behörde ungerecht behandelt fühlen oder Missstände in der öffentlichen Verwaltung vermuten, und unterstützen dabei, diese Beschwerden zu klären"}, {"kategorie": "", "text": "Die zentrale Ombudseinrichtung in Österreich ist die [[Volksanwaltschaft]]. Sie wurde 1977 gegründet und ist in der [[österreichischen]] Bundesverfassung verankert. Die Volksanwaltschaft ist unabhängig und arbeitet als Kontrollinstanz für die öffentliche Verwaltung. Sie überprüft Verwaltungsakte und Maßnahmen der Verwaltung auf Rechtmäßigkeit und kümmert sich um den Schutz und die Durchsetzung der Bürgerrechte"}, {"kategorie": "", "text": "Neben der Volksanwaltschaft gibt es in Österreich noch andere Ombudseinrichtungen und spezialisierte Anlaufstellen für bestimmte Bereiche:  (i) [[Kinder-]] und Jugendanwaltschaften: Jedes österreichische Bundesland hat eine Kinder- und Jugendanwaltschaft, die sich für die Rechte und den Schutz von Kindern und Jugendlichen einsetzt und Beschwerden oder Anliegen von Kindern, Jugendlichen und deren Eltern bearbeitet;  (ii) [[Gleichbehandlungsanwaltschaft]]: Die Gleichbehandlungsanwaltschaft setzt sich gegen Diskriminierung am Arbeitsplatz oder in anderen Lebensbereichen ein und unterstützt Betroffene bei der Durchsetzung ihres Anspruchs auf Gleichbehandlung;  (iii) [[Patientenanwaltschaften]]: In den Bundesländern gibt es Patientenanwaltschaften, die Bürger bei Anliegen und Beschwerden im Gesundheitsbereich unterstützen und bei Konflikten mit Gesundheitseinrichtungen vermitteln"}, {"kategorie": "", "text": "Ombudseinrichtungen spielen eine zentrale Rolle im österreichischen Rechtsschutzsystem, da sie den Bürgern einen einfachen und kostenlosen Zugang zu Rechtsbeistand und Beratung bieten. Sie fördern das Vertrauen in die öffentliche Verwaltung, indem sie Missstände transparent machen und zur fairen Behandlung der Bürger beitragen. Obwohl ihre Empfehlungen nicht bindend sind, sorgen sie durch ihre Prüf- und Kontrollfunktion für die Einhaltung von Rechtsstaatlichkeit und Bürgerrechten."}]'::jsonb, ''),
  ('voiksaunwoidschoft', 'Voiksaunwoidschoft', '', '', '', '', 'Volksanwaltschaft', '[{"kategorie": "jur.", "text": "\"unabhängige und verfassungsrechtlich verankerte Kontrollinstanz der öffentlichen Verwaltung in Österreich\""}, {"kategorie": "", "text": "Sie wurde 1977 gegründet und hat die Aufgabe, Bürgerrechte zu schützen und Missstände in der [[Verwaltung]] aufzudecken und zu beheben"}, {"kategorie": "", "text": "Die Volksanwaltschaft überprüft auf Bundes-, Landes- und Gemeindeebene die Rechtmäßigkeit und Fairness von Verwaltungshandlungen und geht Beschwerden nach, wenn Bürger sich durch Behörden ungerecht behandelt fühlen"}, {"kategorie": "", "text": "Wenn die Volksanwaltschaft einen Missstand in der Verwaltung feststellt, gibt sie Empfehlungen zur Beseitigung des Problems ab. Diese Empfehlungen sind zwar nicht rechtsverbindlich, die betroffenen Behörden sind jedoch verpflichtet, dazu Stellung zu nehmen und Maßnahmen zu ergreifen"}, {"kategorie": "", "text": "Die Volksanwaltschaft hat die Aufgabe, die Einhaltung der [[Menschenrechte]] in staatlichen Einrichtungen zu überwachen. Dazu gehören Haftanstalten, Pflegeheime, psychiatrische Einrichtungen und Asylunterkünfte. In dieser Funktion arbeitet die Volksanwaltschaft mit Kommissionen und einem [[Menschenrechtsbeirat]] zusammen, die präventive Kontrollen durchführen und Missstände aufdecken"}, {"kategorie": "", "text": "Die Volksanwaltschaft erstattet dem [[Nationalrat]] jährlich Bericht über ihre Tätigkeit. Diese Berichte sind öffentlich zugänglich und enthalten Informationen zu den geprüften Fällen, den festgestellten Missständen und den abgegebenen Empfehlungen"}, {"kategorie": "", "text": "Neben der Berichterstattung arbeitet die Volksanwaltschaft aktiv an der Aufklärung und Information der Bevölkerung. Sie geht an die Öffentlichkeit, um über Missstände zu informieren, und trägt zur Transparenz in der Verwaltung bei"}, {"kategorie": "", "text": "Die Volksanwaltschaft besteht aus drei Mitgliedern, die vom Nationalrat auf eine Amtszeit von sechs Jahren gewählt werden. Jedes Mitglied leitet einen Geschäftsbereich und ist eigenständig für bestimmte Verwaltungsbereiche zuständig. Die Mitglieder der Volksanwaltschaft müssen unabhängig und unparteiisch arbeiten und dürfen keiner politischen Weisung unterliegen"}, {"kategorie": "", "text": "Die Volksanwaltschaft ist eine zentrale Institution des [[Rechtsschutzes]] und trägt maßgeblich zur Einhaltung der [[Rechtsstaatlichkeit]] und [[Menschenrechte]] bei. Sie gibt Bürgern eine Anlaufstelle, um sich gegen unfaire oder fehlerhafte Verwaltungsentscheidungen zu wehren, und fördert durch ihre Prüf- und Kontrolltätigkeit Transparenz und Vertrauen in die öffentliche Verwaltung. Durch ihre Arbeit in der Menschenrechtskontrolle trägt die Volksanwaltschaft zudem zum Schutz besonders vulnerabler Gruppen bei."}]'::jsonb, ''),
  ('gleichbehaundlungsaunwoidschoft', 'Gleichbehaundlungsaunwoidschoft', '', '', '', '', 'Gleichbehandlungsanwaltschaft', '[{"kategorie": "", "text": "Sie wurde eingerichtet, um Bürger bei Diskriminierungen am Arbeitsplatz und im Alltag zu unterstützen, die durch Geschlecht, ethnische Zugehörigkeit, Religion, Weltanschauung, Alter oder sexuelle Orientierung begründet sind"}, {"kategorie": "", "text": "Die Gleichbehandlungsanwaltschaft ist eine zentrale Institution für die Durchsetzung der Gleichbehandlungsrechte und gehört zum Bundesministerium für Frauen, Familien, Integration und Medien"}, {"kategorie": "", "text": "Die Gleichbehandlungsanwaltschaft bietet kostenlose Beratung für Menschen an, die sich aufgrund eines oder mehrerer Diskriminierungsmerkmale benachteiligt fühlen. Die GAW informiert über Rechte und Unterstützungsmöglichkeiten und bietet Hilfe bei der weiteren Vorgehensweise"}, {"kategorie": "", "text": "Die GAW überprüft Fälle von Diskriminierung auf gesetzlicher Grundlage und dokumentiert diese. Sie hilft dabei, Fälle nach dem [[Gleichbehandlungsgesetz]] zu beurteilen und mögliche Rechtsverletzungen festzustellen"}, {"kategorie": "", "text": "In Zusammenarbeit mit der [[Gleichbehandlungskommission]] kann die Gleichbehandlungsanwaltschaft Verfahren einleiten, um festzustellen, ob eine Diskriminierung vorliegt. Die Kommission erstellt dann ein Gutachten, das allerdings nicht bindend ist, jedoch zur Orientierung und Schlichtung beiträgt"}, {"kategorie": "", "text": "Die Gleichbehandlungsanwaltschaft informiert die Öffentlichkeit über Diskriminierung und Gleichbehandlung. Sie führt Kampagnen durch, veröffentlicht Berichte und setzt sich für die Stärkung der gesellschaftlichen Sensibilität in Bezug auf Gleichberechtigung und Diskriminierung ein"}, {"kategorie": "", "text": "Die GAW unterstützt diskriminierte Personen darin, ihre Ansprüche gerichtlich geltend zu machen, indem sie bei der Vorbereitung und Begleitung von Gerichtsverfahren berät. Obwohl sie keine rechtliche Vertretung vor Gericht übernimmt, ist sie ein wichtiger Partner für die Betroffenen im Diskriminierungsschutz"}, {"kategorie": "", "text": "Die Gleichbehandlungsanwaltschaft erstellt regelmäßige Berichte, die dem [[Nationalrat]] vorgelegt werden und die aktuelle Lage in Bezug auf Gleichbehandlung und Diskriminierung in Österreich dokumentieren. Sie spricht auch Empfehlungen zur Verbesserung des Diskriminierungsschutzes aus"}, {"kategorie": "", "text": "Die Zuständigkeit der Gleichbehandlungsanwaltschaft deckt verschiedene Bereiche ab:  (i) Arbeitswelt: Diskriminierungen im Arbeitsumfeld, etwa im Bewerbungsprozess, bei Beförderungen, der Entlohnung oder beim Kündigungsschutz;  (ii) Zugang zu Gütern und Dienstleistungen: Diskriminierungen im Zugang zu öffentlich angebotenen Waren und Dienstleistungen, z.B. im Bereich Wohnungsmarkt, Banken oder Freizeitangebote;  (iii) Bildung und Sozialschutz: Diskriminierungen im Bildungsbereich sowie im Bereich der sozialen Sicherheit und Gesundheitsversorgung"}, {"kategorie": "", "text": "Die Gleichbehandlungsanwaltschaft basiert auf dem [[Gleichbehandlungsgesetz]] (GlBG), das Diskriminierungen in verschiedenen Lebensbereichen verbietet und den Rahmen für die Gleichbehandlungskommission und die GAW schafft. Das GlBG legt fest, dass Menschen vor Diskriminierung aufgrund von Geschlecht, ethnischer Herkunft, Religion, Weltanschauung, Alter und sexueller Orientierung geschützt sind."}]'::jsonb, ''),
  ('gleichbehaundlungsgesetz', 'Gleichbehaundlungsgesetz', '', '', '', '', 'Gleichbehandlungsgesetz', '[{"kategorie": "", "text": "Es trat 2004 in Kraft und wurde als Umsetzung europäischer Antidiskriminierungsrichtlinien geschaffen. Das Gleichbehandlungsgesetz bildet die rechtliche Grundlage für die Arbeit der [[Gleichbehandlungsanwaltschaft]] und der [[Gleichbehandlungskommission]]"}, {"kategorie": "", "text": "Das Gleichbehandlungsgesetz hat das Ziel, Diskriminierung zu verhindern und die Gleichbehandlung aller Personen zu fördern. Es deckt mehrere Lebens- und Arbeitsbereiche ab:  (i) Arbeitswelt und Beruf: Das GlBG schützt Arbeitnehmer vor Diskriminierung am Arbeitsplatz, z. B. bei Einstellung, Arbeitsbedingungen, Entlohnung, Beförderungen und Kündigungen. Arbeitgeber sind verpflichtet, alle Beschäftigten gleich zu behandeln und Diskriminierung zu verhindern. Dazu gehört auch, dass Belästigungen und sexuelle Belästigung am Arbeitsplatz untersagt sind;  (ii) Zugang zu Gütern und Dienstleistungen: Das Gesetz schützt Personen vor Diskriminierung beim Zugang zu öffentlich angebotenen Waren und Dienstleistungen, wie z. B. in Geschäften, bei Banken, in Restaurants, auf dem Wohnungsmarkt und in Freizeitangeboten. Das Verbot der Diskriminierung in diesem Bereich gilt insbesondere für ethnische Herkunft und Geschlecht;  (iii) Bildung und Sozialschutz: Das Gleichbehandlungsgesetz gilt auch im Bildungsbereich sowie im Bereich der sozialen Sicherheit und Gesundheitsversorgung. Das bedeutet, dass Menschen gleichberechtigten Zugang zu Bildungseinrichtungen und sozialen Dienstleistungen haben müssen, ohne diskriminiert zu werden"}, {"kategorie": "", "text": "Das Gesetz verbietet Diskriminierung aufgrund von Geschlecht, ethnischer Zugehörigkeit, Religion und Weltanschauung, Alter sowie sexueller Orientierung"}, {"kategorie": "", "text": "Personen, die aufgrund der genannten Merkmale diskriminiert wurden, haben Anspruch auf Schadenersatz. Sie können entweder vor der [[Gleichbehandlungskommission]] oder bei [[Gericht]] eine [[Klage]] einreichen, um Entschädigung für die erlittene Diskriminierung zu erhalten."}]'::jsonb, ''),
  ('patientnaunwoidschoft', 'Patientnaunwoidschoft', '', '', '', '', 'Patientenanwaltschaft', '[{"kategorie": "jur.", "text": "\"unabhängige und weisungsfreie [[Ombudsstelle]], die Patienten im Gesundheitsbereich unterstützt und deren Rechte gegenüber medizinischen Einrichtungen wie Krankenhäusern, Pflegeheimen und Ärzten vertritt\""}, {"kategorie": "", "text": "Sie dient als Anlaufstelle für Patienten, die Beschwerden haben, sich über Behandlungsfehler oder Fehlverhalten informieren möchten oder Unterstützung in Fragen des Gesundheitswesens benötigen"}, {"kategorie": "", "text": "Die Patientenanwaltschaft ist auf Länderebene organisiert, sodass jedes [[Bundesland]] in Österreich eine eigene Patientenanwaltschaft unterhält"}, {"kategorie": "", "text": "Die Patientenanwaltschaft bietet Patienten und deren Angehörigen Beratung in medizinischen und rechtlichen Fragen rund um die Gesundheitsversorgung an. Sie informiert über Patientenrechte, medizinische Standards und gesetzliche Ansprüche, z. B. über Aufklärungspflichten, Behandlungsstandards und Rechte bei Operationen oder Therapien"}, {"kategorie": "", "text": "Patienten können sich bei der Patientenanwaltschaft beschweren, wenn sie sich durch eine medizinische Behandlung oder durch den Umgang in einer Gesundheitseinrichtung benachteiligt oder falsch behandelt fühlen. Die Patientenanwaltschaft prüft die Beschwerden und versucht, Lösungen zu finden oder Missstände zu beheben"}, {"kategorie": "", "text": "Im Falle eines vermuteten Behandlungsfehlers hilft die Patientenanwaltschaft Patienten dabei, den Fall zu klären und gegebenenfalls Schadenersatzansprüche geltend zu machen. Sie vermittelt in Streitfällen und unterstützt bei der Kontaktaufnahme mit Versicherungen oder bei der Vorbereitung einer gerichtlichen [[Klage]]"}, {"kategorie": "", "text": "Die Patientenanwaltschaft agiert als Vermittler zwischen Patienten und Gesundheitseinrichtungen. Sie versucht, Konflikte außergerichtlich zu lösen und durch Dialog und Mediation eine Einigung zu erzielen, die den Interessen beider Seiten gerecht wird"}, {"kategorie": "", "text": "Die Unabhängigkeit der Patientenanwaltschaft ist gesetzlich verankert, und die Finanzierung erfolgt in der Regel durch das jeweilige Bundesland, oft in Zusammenarbeit mit Gesundheitsinstitutionen"}, {"kategorie": "", "text": "Die Patientenanwaltschaft ist eine wichtige Institution für den Schutz der Patientenrechte und die Qualitätssicherung im Gesundheitswesen. Sie gibt den Patienten eine Stimme und bietet eine niederschwellige Möglichkeit, Unterstützung und Hilfe bei Problemen im Gesundheitsbereich zu erhalten."}]'::jsonb, ''),
  ('menschnrechte', 'Menschnrechte', '', '', '', '', 'Menschenrechte', '[{"kategorie": "jur.", "text": "\"grundlegende Rechte, die jedem Menschen unabhängig von seiner Herkunft, Religion, Nationalität oder sozialen Stellung zustehen\""}, {"kategorie": "", "text": "Sie schützen die Würde, Freiheit und Gleichheit aller Menschen und garantieren ihnen grundlegende Freiheiten und Schutz vor staatlichen Eingriffen"}, {"kategorie": "", "text": "In Österreich sind Menschenrechte ein zentraler Bestandteil der [[Verfassungsordnung]] und sind in mehreren Rechtsquellen fest verankert:  (i) [[Staatsgrundgesetz]] von 1867: Das Staatsgrundgesetz über die allgemeinen Rechte der Staatsbürger ist ein zentrales [[Verfassungsgesetz]], das viele klassische Grundrechte enthält, wie die [[Freiheit]] der Person, die [[Eigentumsfreiheit]], die [[Meinungsfreiheit]] und die [[Gleichheit]] vor dem Gesetz. Obwohl es ursprünglich als Gesetz für Staatsbürger formuliert wurde, gelten diese Rechte heute als allgemeine Menschenrechte;  (ii) [[Europäische]] Menschenrechtskonvention (EMRK): Die EMRK, die 1950 vom Europarat verabschiedet wurde, ist seit 1964 in Österreich in Verfassungsrang und gilt somit als oberstes Recht. Die EMRK sichert den Menschen in Österreich Rechte wie das [[Recht]] auf Leben, das Verbot der Folter, das [[Recht]] auf ein faires Verfahren, die [[Meinungsfreiheit]] und das Recht auf Privat- und Familienleben. Jeder Bürger kann sich bei Menschenrechtsverletzungen an den [[Europäischen]] Gerichtshof für Menschenrechte (EGMR) wenden;  (iii) Charta der Grundrechte der Europäischen Union: Seit dem Beitritt Österreichs zur Europäischen Union im Jahr 1995 gilt auch die EU-Grundrechtecharta als verbindliche Quelle für die Menschenrechte, insbesondere bei allen Belangen, die unter das EU-Recht fallen. Sie garantiert Rechte wie den Schutz der Menschenwürde, das Recht auf Gleichheit und das Recht auf Bildung und Berufsfreiheit"}, {"kategorie": "", "text": "Inhalt und Beispiele von Menschenrechten in Österreich:  (i) [[Recht]] auf Leben: Schutz des Lebens jedes Menschen;  (ii) [[Freiheit]] der Person: Schutz vor willkürlicher Festnahme und Inhaftierung;  (iii) [[Meinungs-]] und Informationsfreiheit: Das Recht, die eigene Meinung frei zu äußern und sich aus verschiedenen Quellen zu informieren;  (iv) [[Religionsfreiheit]]: Die Freiheit, seine Religion zu wählen und zu praktizieren;  (v) [[Versammlungs-]] und Vereinsfreiheit: Das Recht, sich friedlich zu versammeln und Vereinigungen zu gründen;  (vi) Recht auf Bildung: Zugang zu Bildung und Chancengleichheit im Bildungssystem;  (vii) Schutz der Arbeitnehmerrechte, z. B. durch das Recht auf gerechte Arbeitsbedingungen und den Schutz vor Diskriminierung am Arbeitsplatz;  (vii) Recht auf soziale Sicherheit: Anspruch auf soziale Absicherung und Unterstützung in Notlagen;  (viii) Schutz vor Diskriminierung und Gleichheitsgrundsatz: Alle Menschen sind vor dem Gesetz gleich und dürfen aufgrund ihres Geschlechts, ihrer ethnischen Zugehörigkeit, Religion, ihres Alters oder ihrer sexuellen Orientierung nicht diskriminiert werden. Der Gleichheitsgrundsatz ist zentral für die Umsetzung der Menschenrechte in Österreich"}, {"kategorie": "", "text": "Der [[Verfassungsgerichtshof]] (VfGH) überwacht die Einhaltung der Menschenrechte und kann Gesetze, die gegen die Menschenrechte verstoßen, aufheben. Er schützt die [[Grund-]] und Freiheitsrechte und sorgt dafür, dass alle staatlichen Organe die Verfassung einhalten"}, {"kategorie": "", "text": "Die [[Volksanwaltschaft]] und die [[Gleichbehandlungsanwaltschaft]] sind [[Ombudsstellen]], die Bürger bei der Durchsetzung ihrer Rechte unterstützen und Beschwerden über Menschenrechtsverletzungen und Diskriminierungen entgegennehmen"}, {"kategorie": "", "text": "Österreichische Bürger können sich auch an den [[Europäischen]] Gerichtshof für Menschenrechte (EGMR) wenden, wenn sie alle nationalen Instanzen ausgeschöpft haben und der Meinung sind, dass ihre Menschenrechte verletzt wurden. Der EGMR kann den Staat zur Einhaltung der Menschenrechte verpflichten und gegebenenfalls Entschädigungen festlegen"}, {"kategorie": "", "text": "Die Menschenrechte bilden das Fundament des österreichischen Rechtsstaates und schützen die Freiheit und Würde jedes Einzelnen. Sie garantieren, dass der Staat nicht willkürlich handeln kann und dass Bürger vor staatlichen Eingriffen geschützt sind. Menschenrechte fördern Gleichheit, Toleranz und Demokratie in Österreich und schaffen das rechtliche und ethische Fundament für ein friedliches und gerechtes Zusammenleben."}]'::jsonb, ''),
  ('menschnrechtsbeiroot', 'Menschnrechtsbeiroot', '', '', '', '', 'Menschenrechtsbeirat', '[{"kategorie": "pol.", "text": "\"unabhängiges Gremium in Österreich, das die Aufgabe hat, die Einhaltung der Menschenrechte in staatlichen Einrichtungen und im Handeln der Behörden zu überwachen und zu fördern\""}, {"kategorie": "", "text": "Ursprünglich wurde er im Jahr 1999 eingerichtet und ist heute ein integraler Bestandteil der [[Volksanwaltschaft]], die in Österreich für den Schutz und die Förderung der Menschenrechte zuständig ist. Der Menschenrechtsbeirat unterstützt die Volksanwaltschaft insbesondere bei der Prävention von Menschenrechtsverletzungen in öffentlichen Institutionen, wie etwa [[Justizanstalten]], Pflegeheimen und Asylunterkünften"}, {"kategorie": "", "text": "Der Beirat gibt Empfehlungen an staatliche Stellen ab, wie die Menschenrechtssituation in bestimmten Bereichen verbessert werden kann. Diese Empfehlungen sind rechtlich nicht bindend, werden jedoch von den betroffenen Einrichtungen und Behörden oft berücksichtigt"}, {"kategorie": "", "text": "Der Menschenrechtsbeirat arbeitet mit internationalen Menschenrechtsorganisationen und Netzwerken zusammen, insbesondere mit solchen, die in Europa tätig sind. Dadurch kann er seine Standards weiterentwickeln und die Einhaltung internationaler Menschenrechtsnormen förder"}, {"kategorie": "", "text": "Der Menschenrechtsbeirat besteht aus Expertinnen und Experten aus verschiedenen Fachbereichen, darunter Recht, Medizin, Psychologie und Sozialarbeit, die über fundierte Kenntnisse im Bereich der Menschenrechte verfügen. Mitglieder des Beirats werden auf Vorschlag von Fachorganisationen und [[Interessenvertretungen]] ernannt, um eine unabhängige und interdisziplinäre Perspektive sicherzustellen. Der Beirat arbeitet eng mit der [[Volksanwaltschaft]] und den von ihr eingesetzten Kommissionen zusammen, die vor Ort in Einrichtungen Inspektionen durchführen"}, {"kategorie": "", "text": "Die Arbeit des Menschenrechtsbeirats basiert auf dem Volksanwaltschaftsgesetz und orientiert sich an internationalen menschenrechtlichen Standards. Österreich ist zudem an das OPCAT (Optional Protocol to the Convention against Torture) gebunden, ein Zusatzprotokoll zur Anti-Folter-Konvention der Vereinten Nationen, das Österreich dazu verpflichtet, nationale Präventionsmechanismen gegen Folter und Misshandlungen zu etablieren. Der Menschenrechtsbeirat erfüllt diese Verpflichtung für Österreich in Zusammenarbeit mit der Volksanwaltschaft."}]'::jsonb, ''),
  ('gleichbehaundlungskommission', 'Gleichbehaundlungskommission', '', '', '', '', 'Gleichbehandlungskommission', '[{"kategorie": "", "text": "Sie ist in erster Linie dafür zuständig, festzustellen, ob Diskriminierungen vorliegen, und sie gibt in solchen Fällen Gutachten und Empfehlungen ab"}, {"kategorie": "", "text": "Die Gleichbehandlungskommission wird auf Grundlage des [[Gleichbehandlungsgesetzes]] (GlBG) tätig und arbeitet eng mit der [[Gleichbehandlungsanwaltschaft]] zusammen"}, {"kategorie": "", "text": "Die Gleichbehandlungskommission prüft Fälle, bei denen eine Diskriminierung aufgrund des Geschlechts, der ethnischen Zugehörigkeit, der Religion, der Weltanschauung, des Alters oder der sexuellen Orientierung vermutet wird. Diese Prüfungen erfolgen auf Antrag der betroffenen Person oder nach Einleitung durch die [[Gleichbehandlungsanwaltschaft]]"}, {"kategorie": "", "text": "Die Kommission erstellt Gutachten, in denen sie feststellt, ob eine Diskriminierung vorliegt. Diese Gutachten sind rechtlich nicht bindend, haben jedoch eine wichtige Orientierungsfunktion. Arbeitgeber und andere Beteiligte sind dazu angehalten, sich an den Empfehlungen der Kommission zu orientieren, um diskriminierendes Verhalten abzustellen"}, {"kategorie": "", "text": "Die Gleichbehandlungskommission arbeitet eng mit der [[Gleichbehandlungsanwaltschaft]] zusammen, die diskriminierte Personen berät und bei der Einleitung eines Verfahrens vor der Kommission unterstützt"}, {"kategorie": "", "text": "Die Kommission erstellt regelmäßig Berichte, die die aktuelle Lage in Bezug auf Diskriminierung und Gleichbehandlung in Österreich aufzeigen und zur Sensibilisierung der Öffentlichkeit beitragen. Diese Berichte werden dem [[Nationalrat]] vorgelegt und sind öffentlich zugänglich"}, {"kategorie": "", "text": "Die Gleichbehandlungskommission ist in drei Senate unterteilt, die jeweils auf unterschiedliche Bereiche spezialisiert sind:  (i) Senat I: Zuständig für Diskriminierung aufgrund des Geschlechts in Beschäftigung und Beruf, insbesondere in den Bereichen Entlohnung, Beförderung, Arbeitsbedingungen und Zugang zum Beruf;  (ii) Senat II: Behandelt Fälle von Diskriminierung aufgrund ethnischer Zugehörigkeit, Religion, Weltanschauung, Alter und sexueller Orientierung, ebenfalls im Bereich Beschäftigung und Beruf;  (iii) Senat III: Befasst sich mit Diskriminierungen aufgrund ethnischer Zugehörigkeit und Geschlecht im Bereich des Zugangs zu und der Versorgung mit Gütern und Dienstleistungen, die der Öffentlichkeit zur Verfügung stehen, einschließlich Wohnungsmarkt, Bildung und sozialer Schutz"}, {"kategorie": "", "text": "Jeder Senat besteht aus mehreren Mitgliedern, die über spezielle Kenntnisse im Bereich Gleichbehandlung und Antidiskriminierung verfügen. Die Mitglieder der Kommission werden von der [[Bundesregierung]] ernannt, arbeiten jedoch unabhängig und sind in ihren Entscheidungen weisungsfrei"}, {"kategorie": "", "text": "Verfahren vor der Gleichbehandlungskommission:  (i) Einleitung des Verfahrens: Ein Verfahren kann entweder durch eine betroffene Person oder die [[Gleichbehandlungsanwaltschaft]] eingeleitet werden;  (ii) Prüfung und Anhörung: Die Kommission prüft den Fall und kann Anhörungen durchführen, bei denen die betroffenen Parteien ihre Sichtweise darlegen;  (iii) Gutachten und Empfehlungen: Die Gleichbehandlungskommission erstellt abschließend ein Gutachten, in dem sie feststellt, ob eine Diskriminierung vorliegt, und gibt gegebenenfalls Empfehlungen zur Beseitigung der Diskriminierung ab."}]'::jsonb, ''),
  ('intaressnsvatretung', 'Intaressnsvatretung', '', '', '', '', 'Interessensvertretung', '[{"kategorie": "allg.", "text": "\"Organisation oder Institution in Österreich, welche die gemeinsamen Interessen und Anliegen einer bestimmten Gruppe von Personen oder Unternehmen vertritt und diese gegenüber staatlichen Stellen, der Öffentlichkeit oder anderen Organisationen durchzusetzen versucht\""}, {"kategorie": "", "text": "Interessensvertretungen sind in Österreich gesetzlich verankert und spielen eine wichtige Rolle im politischen System sowie im sozialen und wirtschaftlichen Leben. Sie umfassen sowohl berufliche und wirtschaftliche als auch soziale Gruppen und fungieren als Schnittstelle zwischen Bürgern, Unternehmen und dem Staat"}, {"kategorie": "", "text": "Arten von Interessensvertretungen in Österreich:  (i) Arbeiterkammer (AK): Die Arbeiterkammer ist die gesetzliche Interessensvertretung der Arbeitnehmer. Sie setzt sich für Arbeitnehmerrechte ein, bietet Beratung und Schulungen an und vertritt ihre Mitglieder in arbeitsrechtlichen Fragen;  (ii) Wirtschaftskammer (WK): Die Wirtschaftskammer ist die Interessensvertretung der Unternehmer und Selbstständigen. Sie unterstützt Unternehmen in wirtschaftlichen, rechtlichen und steuerlichen Fragen und nimmt Einfluss auf wirtschaftspolitische Entscheidungen;  (iii) Landwirtschaftskammer (LK): Die Landwirtschaftskammer vertritt die Interessen der Landwirte und landwirtschaftlichen Betriebe. Sie berät ihre Mitglieder, fördert die Landwirtschaft und engagiert sich in landwirtschaftspolitischen Fragen;  (iv) Industriellenvereinigung (IV): Die Industriellenvereinigung repräsentiert die Interessen der Industrieunternehmen in Österreich und ist eine freiwillige Interessensvertretung, die die Wettbewerbsfähigkeit und Innovation in der Industrie fördert"}, {"kategorie": "", "text": "Gewerkschaften und Arbeitnehmervertretungen: (i) Österreichischer Gewerkschaftsbund (ÖGB): Der ÖGB ist die Dachorganisation der Gewerkschaften in Österreich und vertritt die Interessen der Arbeitnehmer. Er setzt sich für bessere Arbeitsbedingungen, faire Löhne und soziale Sicherheit ein;  (ii) Betriebsräte: Auf Betriebsebene vertreten Betriebsräte die Interessen der Arbeitnehmer in konkreten Unternehmen. Sie verhandeln über Arbeitsbedingungen und übernehmen Aufgaben des Arbeits- und Gesundheitsschutzes"}, {"kategorie": "", "text": "Soziale und gesellschaftliche Interessensvertretungen;  (i) Vereine und [[NGOs]]: Viele soziale, ökologische und kulturelle Anliegen werden durch [[Nichtregierungsorganisationen]] (NGOs) und Vereine vertreten. Dazu gehören Organisationen wie Caritas, Greenpeace und der Naturschutzbund;  (ii) Selbsthilfeorganisationen: Gruppen wie die Behindertenvertretungen oder Patientenorganisationen setzen sich für die Rechte und Interessen von bestimmten Bevölkerungsgruppen ein, wie etwa Menschen mit Behinderungen oder chronischen Erkrankungen"}, {"kategorie": "", "text": "Interessensvertretungen bieten ihren Mitgliedern Beratungsdienste und Informationen in verschiedenen Bereichen wie Recht, Finanzen, Weiterbildung und Arbeitsrecht. Sie unterstützen Mitglieder dabei, ihre Anliegen durchzusetzen und ihre Rechte wahrzunehmen"}, {"kategorie": "", "text": "Viele Interessensvertretungen, insbesondere [[Gewerkschaften]] und [[Wirtschaftskammern]], führen [[Kollektivvertragsverhandlungen]] durch, um Arbeitsbedingungen und Löhne festzulegen. Sie wirken als Vermittler bei Konflikten zwischen Arbeitgebern und Arbeitnehmern oder zwischen Staat und Wirtschaft."}]'::jsonb, '')
